script:
previous = doc.get_doc_before_save()

if previous:
    old_state = previous.workflow_state
    new_state = doc.workflow_state

    # Assign only when moving to In progress
    if old_state != "In progress" and new_state == "In progress":

        # Ensure all lines have approver_user
        missing = []
        for r in (doc.clearance_lines or []):
            if not r.approver_user:
                missing.append(r.unit_name or r.unit_type or _("Unknown Unit"))

        if missing:
            msg = _("Cannot issue Clearance before assigning approvers to all units.")
            msg = msg + "\n" + _("Units without approver:")
            msg = msg + "\n" + ", ".join(missing)
            frappe.throw(msg)

        for r in (doc.clearance_lines or []):
            if not r.approver_user:
                continue

            # Avoid duplicates
            already_assigned = frappe.db.exists("ToDo", {
                "reference_type": doc.doctype,
                "reference_name": doc.name,
                "allocated_to": r.approver_user,
                "status": ["!=", "Cancelled"]
            })

            if not already_assigned:
                unit_label = r.unit_name or r.unit_type or _("Unknown Unit")
                emp_label = doc.employee or ""

                todo = frappe.get_doc({
                    "doctype": "ToDo",
                    "allocated_to": r.approver_user,
                    "reference_type": doc.doctype,
                    "reference_name": doc.name,
                    "description": _("Clearance required for:") + " " + unit_label + " (" + _("Employee:") + " " + emp_label + ")",
                    "priority": "Medium",
                    "status": "Open"
                })
                todo.insert(ignore_permissions=True)

# Prevent completion unless all units are cleared
if doc.workflow_state in ["Completed", "Approved"]:

    not_cleared = []
    for row in (doc.clearance_lines or []):
        if (row.clearance_status or "").strip() != "Cleared":
            not_cleared.append(row.unit_name or row.unit_type or _("Unknown Unit"))

    if not_cleared:
        msg = _("Cannot complete or approve Clearance before clearing all units.")
        msg = msg + "\n" + _("Units not cleared:")
        msg = msg + "\n" + ", ".join(not_cleared)
        frappe.throw(msg)

if "created_by_fullname" in doc.meta.get_valid_columns():
    user_fullname = frappe.db.get_value("User", frappe.session.user, "username") or frappe.session.user
    doc.created_by_fullname = user_fullname

try:
    # Get the current user's full name
    user_full_name = frappe.db.get_value("User", frappe.session.user, "full_name")

    if user_full_name:
        doc.sender = user_full_name
    else:
        # Fallback to the User ID (email) if full name is not found
        doc.sender = frappe.session.user
        frappe.msgprint(f"{doc.sender=}")
except Exception as e:
    # Log the error and fallback to User ID
    frappe.log_error(f"Failed to set sender for Internal Request {doc.name or 'New'}: {e}", "Autofill Sender Script")
    doc.sender = frappe.session.user

def set_serial_number(doc):
    book_type = doc.book_t

    # تحديد القيمة الابتدائية حسب نوع الكتاب
    if book_type == "قرار":
        start_num = 325
    elif book_type == "تعميم":
        start_num = 39
    elif book_type == "بلاغ":
        start_num = 2
    else:
        return

    # 🔴 استخدم Fieldname بالإنجليزي بدل الاسم العربي
    fieldname = "serial_no"  # ← غير هذا إلى الاسم الحقيقي للحقل في الـ Doctype

    last_doc = frappe.get_all(
        "diwan",
        filters={
            "book_t": book_type,
            fieldname: ["not in", ["", None]],
            "name": ["!=", doc.name]
        },
        fields=[fieldname],
        order_by=f"{fieldname} desc",
        limit=1
    )

    if last_doc:
        try:
            last_no = int(last_doc[0].get(fieldname))
            new_no = max(last_no + 1, start_num)
        except (ValueError, TypeError):
            new_no = start_num
    else:
        new_no = start_num

    # تعيين الرقم المتسلسل
    doc.serial_no = new_no  # ← استخدم الاسم الإنجليزي هنا أيضًا


# استدعاء الدالة
set_serial_number(doc)

if "created_by_fullname" in doc.meta.get_valid_columns():
    user_fullname = frappe.db.get_value("User", frappe.session.user, "username") or frappe.session.user
    doc.created_by_fullname = user_fullname

if doc.custodian:
    doc.employee = doc.custodian
else:
    doc.employee = None

frappe.response["message"] = "hello"
frappe.response["data"] = []

def norm(v):
    if v is None:
        return None
    v = str(v).strip()
    if v == "" or v.lower() in ("null", "none", "undefined"):
        return None
    return v

def parse_assign(raw):
    """Return list of assigned user IDs from _assign JSON, safely."""
    if not raw:
        return []
    try:
        arr = json.loads(raw) if isinstance(raw, str) else raw
        if isinstance(arr, list):
            return [u for u in arr if isinstance(u, str) and u.strip()]
        return []
    except Exception:
        return []

# ===== Read params =====
project     = norm(frappe.form_dict.get("project"))
parent_task = norm(frappe.form_dict.get("parent_task"))
department  = norm(frappe.form_dict.get("department"))
status      = norm(frappe.form_dict.get("status"))   # supports "Overdue"
user        = norm(frappe.form_dict.get("user"))
from_date   = norm(frappe.form_dict.get("from_date"))
to_date     = norm(frappe.form_dict.get("to_date"))

# ===== Build base filters for Task =====
base_filters = {}

year = frappe.utils.nowdate().split("-")[0]
if not from_date:
    from_date = f"{year}-01-01"
if not to_date:
    to_date = f"{year}-12-31"

if project:
    base_filters["project"] = project
if department:
    base_filters["department"] = department

# Date filters (applied ONLY on leaf matching in Python)
if from_date:
    base_filters["exp_start_date"] = (">=", from_date)
if to_date:
    base_filters["exp_end_date"] = ("<=", to_date)

# ===== Helper: filter by assigned user (_assign JSON array) =====
def assigned_to_user(task, u):
    if not u:
        return True
    return u in parse_assign(task.get("_assign"))

# ---- normalize from/to once to date objects ----
from_date_dt = frappe.utils.getdate(from_date) if from_date else None
to_date_dt   = frappe.utils.getdate(to_date) if to_date else None
today_dt     = frappe.utils.getdate(frappe.utils.nowdate())

def get_derived_status(task_doc):
    """
    Derived status rule:
    If workflow_state == "Working" AND exp_end_date < today -> "Overdue"
    Otherwise keep original workflow_state.
    """
    st = (task_doc.get("status") or "").strip()  # status is aliased from workflow_state
    e = task_doc.get("exp_end_date")
    e_dt = frappe.utils.getdate(e) if e else None

    if st == "Working" and e_dt and e_dt < today_dt:
        return "Overdue"
    return st

def leaf_matches_filters(task_doc):
    # Date checks on leaves only
    s = task_doc.get("exp_start_date")
    e = task_doc.get("exp_end_date")
    s_dt = frappe.utils.getdate(s) if s else None
    e_dt = frappe.utils.getdate(e) if e else None

    if from_date_dt:
        if (not s_dt) or (s_dt < from_date_dt):
            return False
    if to_date_dt:
        if (not e_dt) or (e_dt > to_date_dt):
            return False

    # ✅ user filter on leaf only
    if user and (not assigned_to_user(task_doc, user)):
        return False

    derived = get_derived_status(task_doc)
    if status and (derived or "").strip() != status:
        return False

    return True

# ===== Fetch ROOTS (group tasks) =====
roots_filters = dict(base_filters)
roots_filters.pop("exp_start_date", None)
roots_filters.pop("exp_end_date", None)
roots_filters["is_group"] = 1

if parent_task:
    roots_filters["parent_task"] = parent_task
else:
    roots_filters["parent_task"] = ["is", "not set"]

roots = frappe.get_all(
    "Task",
    filters=roots_filters,
    fields=["name", "subject", "workflow_state as status", "parent_task", "description", "_assign", "is_group"]
)

# If no roots, return early with empty payloads (same response shape)
if not roots:
    frappe.response["summary"] = {
        "tasks_per_status": {},
        "completed_tasks_per_user": [],
        "overdue_tasks_per_user": [],
        "done_vs_not_done": {"Done": 0, "Not Done": 0},
        "overdue_vs_ontrack": {"Overdue": 0, "On Track": 0},
    }
    frappe.response["top_performers"] = []
    frappe.response["roots"] = []
    raise SystemExit

root_names = [r["name"] for r in roots]

# ===== FAST FETCH: only tasks under these roots (iterative children fetch) =====
# Keep only stable filters here (project/department). No date filters here.
subtree_filters = {}
if project:
    subtree_filters["project"] = project
if department:
    subtree_filters["department"] = department

TASK_FIELDS = [
    "name", "subject", "workflow_state as status", "parent_task", "description", "_assign", "is_group",
    "exp_start_date", "exp_end_date", "task_weight"
]

tasks = []
fetched = set()
frontier = set(root_names)

# Batch size to avoid very long IN lists
BATCH = 500

while frontier:
    batch = list(frontier)[:BATCH]
    frontier = set(list(frontier)[BATCH:])

    # children of current batch
    q_filters = dict(subtree_filters)
    q_filters["parent_task"] = ["in", batch]

    children_rows = frappe.get_all("Task", filters=q_filters, fields=TASK_FIELDS)

    for row in children_rows:
        nm = row.get("name")
        if not nm or nm in fetched:
            continue
        fetched.add(nm)
        tasks.append(row)
        frontier.add(nm)

# Quick lookup by name
task_by_name = {t["name"]: t for t in tasks}

# ===== Build children map (parent -> [child_names]) =====
children = {}
for t in tasks:
    p = t.get("parent_task")
    if p:
        children.setdefault(p, []).append(t["name"])

# ===== Identify leaf tasks (inside this subtree only) =====
all_names = set(task_by_name.keys())
parent_names = set(children.keys())
leaf_names_set = all_names - parent_names

# ===== Fast descendants traversal (DFS) =====
def get_descendants(root_name):
    out = []
    stack = [root_name]
    visited = set([root_name])
    while stack:
        cur = stack.pop()
        for ch in (children.get(cur) or []):
            if ch in visited:
                continue
            visited.add(ch)
            out.append(ch)
            stack.append(ch)
    return out

# ===== Status summary helpers =====
def summarize_status(leaves):
    summary = {}
    for leaf in leaves:
        st = leaf.get("status") or "Unknown"
        summary[st] = summary.get(st, 0) + 1
    return summary

global_status_summary = {}
completed_per_user = {}
overdue_per_user   = {}
done_vs_not_done = {"Done": 0, "Not Done": 0}
overdue_vs_ontrack = {"Overdue": 0, "On Track": 0}

all_assigned_users = set()
DONE_STATUSES = set(["Done", "Completed"])

# ===== Build leaves per root =====
for r in roots:
    descendants = get_descendants(r["name"])
    leaf_names = [n for n in descendants if n in leaf_names_set]

    leaves = []
    for n in leaf_names:
        t = task_by_name.get(n)
        if not t:
            continue

        if not leaf_matches_filters(t):
            continue

        assigned_list = parse_assign(t.get("_assign"))
        for u in assigned_list:
            all_assigned_users.add(u)

        derived_status = get_derived_status(t)
        orig_status = (t.get("status") or "").strip()

        # per-user counts
        if derived_status in DONE_STATUSES:
            for u in assigned_list:
                completed_per_user[u] = completed_per_user.get(u, 0) + 1

        if derived_status == "Overdue":
            for u in assigned_list:
                overdue_per_user[u] = overdue_per_user.get(u, 0) + 1

        # option C
        if derived_status == "Done":
            done_vs_not_done["Done"] = done_vs_not_done.get("Done", 0) + 1
        else:
            done_vs_not_done["Not Done"] = done_vs_not_done.get("Not Done", 0) + 1

        if derived_status == "Overdue":
            overdue_vs_ontrack["Overdue"] = overdue_vs_ontrack.get("Overdue", 0) + 1
        elif orig_status == "Working":
            overdue_vs_ontrack["On Track"] = overdue_vs_ontrack.get("On Track", 0) + 1

        leaves.append({
            "name": n,
            "subject": t.get("subject"),
            "status": derived_status,
            "description": t.get("description"),
            "exp_start_date": t.get("exp_start_date"),
            "exp_end_date": t.get("exp_end_date"),
            "_assign": t.get("_assign"),
            "task_weight": t.get("task_weight"),
            "assigned_users": assigned_list
        })

        st_key = derived_status or "Unknown"
        global_status_summary[st_key] = global_status_summary.get(st_key, 0) + 1

    r["leaves"] = leaves
    r["leaf_count"] = len(leaves)
    r["leaf_status_summary"] = summarize_status(leaves)

# ✅ when user filter active, remove empty roots
if user:
    roots = [r for r in roots if (r.get("leaves") or [])]

# ===== Fetch user full_name + user_image in ONE query =====
user_info_map = {}
if all_assigned_users:
    users = frappe.get_all(
        "User",
        filters={"name": ["in", list(all_assigned_users)]},
        fields=["name", "full_name", "user_image"]
    )
    for u in users:
        user_info_map[u["name"]] = u

# ===== Replace assigned_users list with objects {user, full_name, user_image} =====
for r in roots:
    for leaf in (r.get("leaves") or []):
        ids = leaf.get("assigned_users") or []
        leaf["assigned_users"] = [
            {
                "user": uid,
                "full_name": (user_info_map.get(uid) or {}).get("full_name") or uid,
                "user_image": (user_info_map.get(uid) or {}).get("user_image")
            }
            for uid in ids
        ]

def build_user_counts_payload(counts_map):
    payload = []
    items = list(counts_map.items())
    items.sort(key=lambda x: x[1], reverse=True)
    for uid, cnt in items:
        info = user_info_map.get(uid) or {}
        payload.append({
            "user": uid,
            "full_name": info.get("full_name") or uid,
            "user_image": info.get("user_image"),
            "count": cnt
        })
    return payload

frappe.response["summary"] = {
    "tasks_per_status": global_status_summary,
    "completed_tasks_per_user": build_user_counts_payload(completed_per_user),
    "overdue_tasks_per_user": build_user_counts_payload(overdue_per_user),
    "done_vs_not_done": done_vs_not_done,
    "overdue_vs_ontrack": overdue_vs_ontrack,
}

# ===== Top performers (sum of done tasks * weight) WITHOUT extra DB call =====
def as_weight(v):
    if v is None:
        return 1
    try:
        vv = float(v)
        return vv if vv > 0 else 1
    except Exception:
        return 1

score_per_user = {}
done_count_per_user = {}

for r in roots:
    for leaf in (r.get("leaves") or []):
        st = (leaf.get("status") or "").strip()
        if st not in DONE_STATUSES:
            continue

        w = as_weight(leaf.get("task_weight"))

        for uo in (leaf.get("assigned_users") or []):
            uid = uo.get("user")
            if not uid:
                continue
            score_per_user[uid] = score_per_user.get(uid, 0) + w
            done_count_per_user[uid] = done_count_per_user.get(uid, 0) + 1

top_items = list(score_per_user.items())
top_items.sort(key=lambda x: x[1], reverse=True)

top_performers_payload = []
for uid, score in top_items:
    info = user_info_map.get(uid) or {}
    top_performers_payload.append({
        "user": uid,
        "full_name": info.get("full_name") or uid,
        "user_image": info.get("user_image"),
        "score": score,
        "done_tasks": done_count_per_user.get(uid, 0)
    })

frappe.response["top_performers"] = top_performers_payload
frappe.response["roots"] = roots

if "created_by_fullname" in doc.meta.get_valid_columns():
    user_fullname = frappe.db.get_value("User", frappe.session.user, "username") or frappe.session.user
    doc.created_by_fullname = user_fullname

# Server Script for Meeting Room Reservation Validation
# Event: Validate

# ============ التحقق 1: تاريخ البداية يجب أن يكون أصغر من أو يساوي تاريخ النهاية ============
if doc.start_date and doc.end_date:
    if doc.start_date > doc.end_date:
        frappe.throw(
            "❌ تاريخ بداية الحجز لا يمكن أن يكون أكبر من تاريخ نهاية الحجز",
            title="خطأ في التواريخ"
        )



# ============ جمع الأيام المختارة ============
selected_days = []
days_fields = {
    'saturday': 'السبت',
    'sunday': 'الاحد',
    'monday': 'الاثنين',
    'tuesday': 'الثلاثاء',
    'wednesday': 'الاربعاء',
    'thursday': 'الخميس',
    'friday': 'الجمعة'
}

for field, day_name in days_fields.items():
    if int(doc.get(field) or 0) == 1:
        selected_days.append(day_name)

# ============ التحقق 2: يجب اختيار يوم واحد على الأقل ============
if not selected_days:
    frappe.throw(
        "❌ يجب اختيار يوم واحد على الأقل للحجز",
        title="أيام الحجز"
    )

# ============ التحقق 3: منع التعارض مع الحجوزات الموجودة ============
if doc.meeting_room and doc.start_date and doc.end_date and doc.start_time and doc.end_time:
    # دالة مساعدة لتحويل الوقت إلى ثواني (تعمل مع timedelta، time object، ونصوص)
    def time_to_seconds(time_val):
        if not time_val:
            return 0
        # إذا كان timedelta
        try:
            return int(time_val.total_seconds())
        except:
            pass
        # إذا كان نص (مثل "09:30:00")
        if isinstance(time_val, str):
            parts = time_val.strip().split(':')
            h = int(parts[0]) if len(parts) > 0 else 0
            m = int(parts[1]) if len(parts) > 1 else 0
            s = int(parts[2]) if len(parts) > 2 else 0
            return h * 3600 + m * 60 + s
        # إذا كان time object
        try:
            return time_val.hour * 3600 + time_val.minute * 60 + time_val.second
        except:
            pass
        # محاولة أخيرة: تحويل إلى نص وتحليل
        try:
            return time_to_seconds(str(time_val))
        except:
            return 0

    # تحويل أوقات الحجز الحالي إلى ثواني
    doc_start_sec = time_to_seconds(doc.start_time)
    doc_end_sec = time_to_seconds(doc.end_time)

    # بناء شروط البحث
    filters = [
        ['meeting_room', '=', doc.meeting_room],
        ['docstatus', '<', 2],
        ['end_date', '>=', doc.start_date],
        ['start_date', '<=', doc.end_date]
    ]
    
    if not doc.is_new():
        filters.append(['name', '!=', doc.name])
    
    existing_bookings = frappe.get_all(
        'Meeting Room Reservation',
        filters=filters,
        fields=[
            'name', 'start_date', 'end_date', 'start_time', 'end_time',
            'saturday', 'sunday', 'monday', 'tuesday', 
            'wednesday', 'thursday', 'friday'
        ]
    )
    
    # التحقق من كل حجز موجود
    for booking in existing_bookings:
        # تحويل أوقات الحجز الموجود إلى ثواني
        booking_start_sec = time_to_seconds(booking.start_time)
        booking_end_sec = time_to_seconds(booking.end_time)
        
        # تحقق من تداخل الوقت (بالمقارنة بالثواني)
        time_conflict = not (
            doc_end_sec <= booking_start_sec or
            doc_start_sec >= booking_end_sec
        )
        
        if time_conflict:
            # تحقق من تداخل الأيام
            existing_days = []
            for field, day_name in days_fields.items():
                if int(booking.get(field) or 0) == 1:
                    existing_days.append(day_name)
            
            if set(selected_days) & set(existing_days):
                days_str = "، ".join(selected_days)
                existing_days_str = "، ".join(existing_days)
                
                frappe.throw(
                    f"❌ القاعة <strong>{doc.meeting_room}</strong> محجوزة مسبقاً في نفس الوقت والأيام<br><br>"
                    f"• حجزك: {doc.start_date} إلى {doc.end_date}، {doc.start_time}–{doc.end_time}، الأيام: {days_str}<br>"
                    f"  من {booking.start_date} إلى {booking.end_date}، "
                    f"{booking.start_time}–{booking.end_time}، الأيام: {existing_days_str}<br><br>"
                    "الحل: غيّر القاعة أو الوقت أو الأيام المختارة",
                    title="حجز متضارب - يرجى التعديل"
                )

if "created_by_fullname" in doc.meta.get_valid_columns():
    user_fullname = frappe.db.get_value("User", frappe.session.user, "username") or frappe.session.user
    doc.created_by_fullname = user_fullname

if "created_by_fullname" in doc.meta.get_valid_columns():
    user_fullname = frappe.db.get_value("User", frappe.session.user, "username") or frappe.session.user
    doc.created_by_fullname = user_fullname

if doc.doctype == "Task" and doc.status == "Approved":
    if not doc.assigned_to and doc.get_doc_before_save():
        doc.assigned_to = doc.get_doc_before_save().assigned_to

# Only allow submission from "Approved By Finance" state
if doc.docstatus == 0 and doc.workflow_state == "Approved":
    doc.docstatus = 1  # Set to submitted

# Server Script API: جلب الحقول الحقيقية من Job Opening
job_opening = frappe.form_dict.get("job_opening")

fields = []

if job_opening:
    try:
        # جلب الحقول من جدول الحقول المخصصة للوظيفة
        custom_fields = frappe.get_all(
            "Job Opening Custom Field Table",  # غيره باسم الـ Doctype الصحيح
            filters={"parent": job_opening},
            fields=["field_label", "field_type", "field_options", "mandatory"]
        )

        for field in custom_fields:
            fieldname = "custom_" + field.field_label.replace(" ", "_").lower()
            fieldname = ''.join(c for c in fieldname if c.isalnum() or c == "_")

            field_def = {
                "fieldname": fieldname,
                "label": field.field_label,
                "fieldtype": field.field_type,
                "reqd": 1 if field.mandatory else 0,
                "options": field.field_options if field.field_type == "Select" else ""
            }
            fields.append(field_def)

    except Exception as e:
        frappe.log_error(f"خطأ في Get_Data: {str(e)}", "Server Script")
        frappe.response["message"] = {"success": False, "fields": [], "error": str(e)}
        raise

# إعادة الداتا كـ JSON
