def get_descendants(root_name):
    """
    Return list of all descendant task names under root_name (excluding root itself).
    Uses children map => much faster than checking all leaves per root.
    """
    out = []
    stack = [root_name]
    visited = set([root_name])
    while stack:
        cur = stack.pop()
        for ch in (children.get(cur) or []):
            if ch in visited:
                continue
            visited.add(ch)
            out.append(ch)
            stack.append(ch)
    return out

