    if age < 15:
        return "<15"
    if age <= 19:
        return "15-19"
    if age <= 24:
        return "20-24"
    if age <= 29:
        return "25-29"
    if age <= 34:
        return "30-34"
    if age <= 39:
        return "35-39"
    if age <= 44:
        return "40-44"
    if age <= 49:
        return "45-49"
    if age <= 54:
        return "50-54"
    if age <= 59:
        return "55-59"
    if age <= 64:
        return "60-64"
    if age <= 69:
        return "65-69"
    if age <= 74:
        return "70-74"
    if age <= 79:
        return "75-79"
    return "80+"

def sort_dict_payload(d, label_key, value_key, keep_zero):
    items = []
    for k in d:
        v = d.get(k, 0)
        if (not keep_zero) and (not v):
            continue
        items.append({
            label_key: k,
            value_key: v
        })
    items.sort(key=lambda x: x.get(value_key, 0), reverse=True)
    return items

def top_n_payload(d, n, label_key, value_key):
    items = sort_dict_payload(d, label_key, value_key, False)
    return items[:n]

def add_months(dt, months):
    y = dt.year + ((dt.month - 1 + months) // 12)
    m = ((dt.month - 1 + months) % 12) + 1

    month_days = {
        1: 31,
        2: 29 if ((y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)) else 28,
        3: 31,
        4: 30,
        5: 31,
        6: 30,
        7: 31,
        8: 31,
        9: 30,
        10: 31,
        11: 30,
        12: 31
    }

    d = dt.day
    if d > month_days[m]:
        d = month_days[m]

    return frappe.utils.getdate(str(y) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2))

