        "leave": "LEAVE",
        "on leave": "LEAVE",
        "إجازة": "LEAVE",

        "absent": "ABSENT",
        "غياب": "ABSENT",

        "weekend": "WEEKEND",

        "holiday": "HOLIDAY",
        "عطلة": "HOLIDAY",
    }

    return mapping.get(txt, value)

