def get_shift_hours(shift_doc):
    if not shift_doc:
        return 0.0

    start_txt = str(shift_doc.start_time or "")
    end_txt = str(shift_doc.end_time or "")

    if " " in start_txt:
        start_txt = start_txt.split(" ")[-1]
    if " " in end_txt:
        end_txt = end_txt.split(" ")[-1]

    sp = start_txt.split(":")
    ep = end_txt.split(":")

    sh = int(sp[0]) if len(sp) > 0 and sp[0] else 0
    sm = int(sp[1]) if len(sp) > 1 and sp[1] else 0
    ss = int(sp[2]) if len(sp) > 2 and sp[2] else 0

    eh = int(ep[0]) if len(ep) > 0 and ep[0] else 0
    em = int(ep[1]) if len(ep) > 1 and ep[1] else 0
    es = int(ep[2]) if len(ep) > 2 and ep[2] else 0

    start_minutes = (sh * 60) + sm
    end_minutes = (eh * 60) + em

    if ss >= 30:
        start_minutes = start_minutes + 1

    if es >= 30:
        end_minutes = end_minutes + 1

    if end_minutes < start_minutes:
        end_minutes = end_minutes + (24 * 60)

    # IMPORTANT:
    # Expected / Shift hours are calculated ONLY from start_time and end_time.
    # No grace period is added here.
    total_minutes = (end_minutes - start_minutes)

    return round2(float(total_minutes or 0) / 60.0)

def top_n_with_others(items, n, others_label):
    sorted_items = sorted(items, key=lambda x: float(x.get("value") or 0), reverse=True)
    top_items = sorted_items[:n]
    rest_items = sorted_items[n:]

    others_total = 0.0
    for item in rest_items:
        others_total = others_total + float(item.get("value") or 0)

    if others_total > 0:
        top_items.append({
            "label": others_label,
            "value": round2(others_total)
        })

    return top_items

def build_date_list(start_date, end_date):
    out = []
    current_date = frappe.utils.getdate(start_date)
    last_date = frappe.utils.getdate(end_date)

    while current_date <= last_date:
        out.append(str(current_date))
        current_date = frappe.utils.add_days(current_date, 1)

    return out

def get_month_name(month_part):
    month_map_en = {
        "01": "Jan", "02": "Feb", "03": "Mar", "04": "Apr",
        "05": "May", "06": "Jun", "07": "Jul", "08": "Aug",
        "09": "Sep", "10": "Oct", "11": "Nov", "12": "Dec"
    }
    return month_map_en.get(month_part, month_part)

def get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift):
    shift_name = employee_date_shift_map.get(emp + "||" + dt)
    if not shift_name:
        shift_name = employee_default_shift.get(emp)
    return shift_name

