resolved_drilldown_dimension = drilldown_dimension
resolved_drilldown_value = drilldown_value

if drilldown_dimension and drilldown_value not in [None, ""]:
    dd = str(drilldown_dimension).strip()
    dv = drilldown_value

    if dd == "company":
        company = dv
    elif dd == "branch":
        branch = dv
    elif dd == "department":
        department = dv
    elif dd == "designation":
        designation = dv
    elif dd == "gender":
        gender = dv
    elif dd == "shift_type":
        shift_type_filter = dv
    elif dd == "employee":
        employee = dv
    elif dd == "employee_name":
        selected_employee_name_drilldown = dv

    elif dd in ["attendance_status_distribution", "attendance_status", "status"]:
        selected_status_drilldown = normalize_status_value(dv)
        resolved_drilldown_dimension = "attendance_status"
        resolved_drilldown_value = get_status_label(selected_status_drilldown)

    elif dd in ["department_actual_hours", "department_unjustified_hours"]:
        department = dv
        resolved_drilldown_dimension = "department"

    elif dd in ["top_employees_by_actual_hours", "top_employees_by_unjustified_hours", "top_employees_by_late_entry"]:
        selected_employee_name_drilldown = dv
        resolved_drilldown_dimension = "employee_name"

# -----------------------------------------------------------------------------
# Employee master filters
# -----------------------------------------------------------------------------
employee_master_filters = {}
if employee:
    employee_master_filters["name"] = employee
if company:
    employee_master_filters["company"] = company
if branch:
    employee_master_filters["branch"] = branch
if department:
    employee_master_filters["department"] = department
if designation:
    employee_master_filters["designation"] = designation
if gender:
    employee_master_filters["gender"] = gender

employee_master_fields = [
    "name",
    "employee_name",
    "company",
    "branch",
    "department",
    "designation",
    "gender",
    "default_shift"
]

employee_id_filter_list = None
employee_details_map = {}

employee_rows = frappe.get_all(
    "Employee",
    filters=employee_master_filters,
    fields=employee_master_fields,
    order_by="name asc"
)

if employee_master_filters and not employee_rows:
    meta = {
        "load_state_text": build_load_state_text(0, resolved_drilldown_dimension, resolved_drilldown_value),
        "drilldown": {
            "source": drilldown_source,
            "dimension": resolved_drilldown_dimension,
            "value": resolved_drilldown_value
        }
    }

    frappe.response["message"] = build_empty_message(columns, meta)

else:
    if employee_rows:
        employee_id_filter_list = [d.name for d in employee_rows]
        for er in employee_rows:
            employee_details_map[er.name] = er

    # -----------------------------------------------------------------------------
    # Attendance query
    # -----------------------------------------------------------------------------
    attendance_filters = {
        "attendance_date": ["between", [from_date, to_date]]
    }

    if employee_id_filter_list is not None:
        attendance_filters["employee"] = ["in", employee_id_filter_list]

    records = frappe.get_all(
        "Attendance",
        filters=attendance_filters,
        fields=[
            "employee",
            "employee_name",
            "department",
            "attendance_date",
            "status",
            "working_hours",
            "in_time",
            "out_time",
            "shift",
            "late_entry",
            "custom_late_entry_in_minutes"
        ],
        order_by="employee asc, attendance_date asc"
    )

    if selected_employee_name_drilldown:
        filtered_records = []
        target_name = str(selected_employee_name_drilldown).strip()
        for r in records:
            r_name = str(r.employee_name or "").strip()
            if r_name == target_name:
                filtered_records.append(r)
        records = filtered_records

    # -----------------------------------------------------------------------------
    # Collect employee list from records
    # -----------------------------------------------------------------------------
    employee_list = []
    employee_seen = {}

    employee_default_shift = {}
    shift_names = []
    shift_seen = {}

    for row in records:
        if row.employee and row.employee not in employee_seen:
            employee_list.append(row.employee)
            employee_seen[row.employee] = 1

        if row.employee and row.shift and row.employee not in employee_default_shift:
            employee_default_shift[row.employee] = row.shift

        if row.shift and row.shift not in shift_seen:
            shift_names.append(row.shift)
            shift_seen[row.shift] = 1

    missing_employee_ids = []
    for emp_id in employee_list:
        if emp_id not in employee_details_map:
            missing_employee_ids.append(emp_id)

    if missing_employee_ids:
        extra_employee_rows = frappe.get_all(
            "Employee",
            filters={"name": ["in", missing_employee_ids]},
            fields=employee_master_fields
        )
        for er in extra_employee_rows:
            employee_details_map[er.name] = er
            if er.name not in employee_default_shift and er.default_shift:
                employee_default_shift[er.name] = er.default_shift

    # -----------------------------------------------------------------------------
    # Shift Assignment query
    # -----------------------------------------------------------------------------
    assignment_filters = {
        "start_date": ["<=", to_date]
    }

    if employee_list:
        assignment_filters["employee"] = ["in", employee_list]

    shift_assignments = frappe.get_all(
        "Shift Assignment",
        filters=assignment_filters,
        fields=[
            "employee",
            "shift_type",
            "start_date",
            "end_date"
        ],
        order_by="employee asc, start_date asc"
    )

    employee_date_shift_map = {}

    for sa in shift_assignments:
        if not sa.employee or not sa.shift_type or not sa.start_date:
            continue

        assignment_start = frappe.utils.getdate(sa.start_date)
        assignment_end = frappe.utils.getdate(sa.end_date) if sa.end_date else frappe.utils.getdate(to_date)
        report_start = frappe.utils.getdate(from_date)
        report_end = frappe.utils.getdate(to_date)

        if assignment_start < report_start:
            assignment_start = report_start

        if assignment_end > report_end:
            assignment_end = report_end

        if assignment_start > assignment_end:
            continue

        if sa.shift_type not in shift_seen:
            shift_names.append(sa.shift_type)
            shift_seen[sa.shift_type] = 1

        d = assignment_start
        while d <= assignment_end:
            employee_date_shift_map[sa.employee + "||" + str(d)] = sa.shift_type
            d = frappe.utils.add_days(d, 1)

    # -----------------------------------------------------------------------------
    # Shift Type query
    # -----------------------------------------------------------------------------
    shift_map = {}
    holiday_list_names = []
    holiday_list_seen = {}

    for emp_id in employee_details_map:
        ds = employee_details_map[emp_id].get("default_shift")
        if ds and ds not in shift_seen:
            shift_names.append(ds)
            shift_seen[ds] = 1

    if shift_names:
        shift_rows = frappe.get_all(
            "Shift Type",
            filters={"name": ["in", shift_names]},
            fields=[
                "name",
                "start_time",
                "end_time",
                "early_exit_grace_period",
                "holiday_list"
            ]
        )

        for shift_row in shift_rows:
            shift_map[shift_row.name] = shift_row

            if shift_row.holiday_list and shift_row.holiday_list not in holiday_list_seen:
                holiday_list_names.append(shift_row.holiday_list)
                holiday_list_seen[shift_row.holiday_list] = 1

    # -----------------------------------------------------------------------------
    # Holiday query
    # -----------------------------------------------------------------------------
    holiday_map = {}

    if holiday_list_names:
        holiday_rows = frappe.get_all(
            "Holiday",
            filters={
                "parent": ["in", holiday_list_names],
                "holiday_date": ["between", [from_date, to_date]]
            },
            fields=[
                "parent",
                "holiday_date",
                "description"
            ]
        )

        for hr in holiday_rows:
            holiday_map[hr.parent + "||" + str(hr.holiday_date)] = {
                "description": (hr.description or "").strip()
            }

    def get_day_off_info(emp, dt):
        shift_name = get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift)

        if shift_name and shift_name in shift_map:
            holiday_list_name = shift_map[shift_name].holiday_list
            if holiday_list_name:
                holiday_row = holiday_map.get(holiday_list_name + "||" + dt)
                if holiday_row:
                    weekday = frappe.utils.getdate(dt).weekday()

                    if weekday in [4, 5]:
                        return {
                            "is_holiday": 1,
                            "status": "WEEKEND",
                            "label": "Weekend"
                        }

                    return {
                        "is_holiday": 1,
                        "status": "HOLIDAY",
                        "label": holiday_row.get("description") or "Holiday"
                    }

        weekday = frappe.utils.getdate(dt).weekday()
        if weekday in [4, 5]:
            return {
                "is_holiday": 1,
                "status": "WEEKEND",
                "label": "Weekend"
            }

        return {
            "is_holiday": 0,
            "status": "",
            "label": ""
        }

    def is_holiday(emp, dt):
        return get_day_off_info(emp, dt).get("is_holiday", 0)

    def get_expected_hours(emp, dt):
        if is_holiday(emp, dt):
            return 0.0

        shift_name = get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift)

        if shift_name and shift_name in shift_map:
            return get_shift_hours(shift_map[shift_name])

        return 0.0

    def day_matches_shift_filter(emp, dt):
        if not shift_type_filter:
            return True
        eff_shift = get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift)
        return eff_shift == shift_type_filter

    # -----------------------------------------------------------------------------
    # Build employee/day matrix
    # -----------------------------------------------------------------------------
    employees_map = {}

    for row in records:
        emp = row.employee
        if not emp:
            continue

        emp_details = employee_details_map.get(emp, {})

        if emp not in employees_map:
            base_row = {
                "employee": emp or "",
                "employee_name": row.employee_name or emp_details.get("employee_name") or "",
                "company": emp_details.get("company") or "",
                "branch": emp_details.get("branch") or "",
                "department": row.department or emp_details.get("department") or "",
                "designation": emp_details.get("designation") or "",
                "gender": emp_details.get("gender") or ""
            }

            for dt in date_list:
                safe_dt = date_field_map[dt]
                if not day_matches_shift_filter(emp, dt):
                    base_row[safe_dt] = ""
                else:
                    day_off_info = get_day_off_info(emp, dt)
                    if day_off_info.get("is_holiday"):
                        base_row[safe_dt] = make_day_cell(
                            day_off_info.get("status", "WEEKEND"),
                            "",
                            "",
                            "",
                            0,
                            day_off_info.get("label", "")
                        )
                    else:
                        base_row[safe_dt] = make_day_cell("ABSENT", "", "", "", 0, "")

            employees_map[emp] = base_row

        day_key = str(row.attendance_date)
        safe_day_key = date_field_map.get(day_key)

        if not safe_day_key:
            continue

        if not day_matches_shift_filter(emp, day_key):
            continue

        status_value = row.status or ""

        if status_value == "Absent":
            day_off_info = get_day_off_info(emp, day_key)
            if day_off_info.get("is_holiday"):
                employees_map[emp][safe_day_key] = make_day_cell(
                    day_off_info.get("status", "WEEKEND"),
                    "",
                    "",
                    "",
                    0,
                    day_off_info.get("label", "")
                )
            else:
                employees_map[emp][safe_day_key] = make_day_cell("ABSENT", "", "", "", 0, "")

        elif status_value == "On Leave":
            leave_day_hours = get_expected_hours(emp, day_key)
            employees_map[emp][safe_day_key] = make_day_cell("LEAVE", leave_day_hours, "", "", 0, "")

        elif status_value == "Work From Home":
            total_hours = 0.0

            if row.shift and row.shift in shift_map:
                total_hours = get_shift_hours(shift_map[row.shift])
            else:
                shift_name = get_effective_shift(emp, day_key, employee_date_shift_map, employee_default_shift)
                if shift_name and shift_name in shift_map:
                    total_hours = get_shift_hours(shift_map[shift_name])

            employees_map[emp][safe_day_key] = make_day_cell("WFH", total_hours, "", "", 0, "")

        elif status_value == "Present":
            in_time = frappe.utils.format_time(row.in_time, "HH:mm") if row.in_time else ""
            out_time = frappe.utils.format_time(row.out_time, "HH:mm") if row.out_time else ""

            if in_time and out_time:
                hours = round2(row.working_hours or 0)
                late_minutes = 0.0

                if row.late_entry:
                    late_minutes = round2(row.custom_late_entry_in_minutes or 0)

                employees_map[emp][safe_day_key] = make_day_cell(
                    "PRESENT",
                    hours,
                    in_time,
                    out_time,
                    late_minutes,
                    ""
                )
            else:
                day_off_info = get_day_off_info(emp, day_key)
                if day_off_info.get("is_holiday"):
                    employees_map[emp][safe_day_key] = make_day_cell(
                        day_off_info.get("status", "WEEKEND"),
                        "",
                        "",
                        "",
                        0,
                        day_off_info.get("label", "")
                    )
                else:
                    employees_map[emp][safe_day_key] = make_day_cell("ABSENT", "", "", "", 0, "")

        else:
            in_time = frappe.utils.format_time(row.in_time, "HH:mm") if row.in_time else ""
            out_time = frappe.utils.format_time(row.out_time, "HH:mm") if row.out_time else ""

            if in_time and out_time:
                hours = round2(row.working_hours or 0)
                late_minutes = 0.0

                if row.late_entry:
                    late_minutes = round2(row.custom_late_entry_in_minutes or 0)

                employees_map[emp][safe_day_key] = make_day_cell(
                    "PRESENT",
                    hours,
                    in_time,
                    out_time,
                    late_minutes,
                    ""
                )
            else:
                day_off_info = get_day_off_info(emp, day_key)
                if day_off_info.get("is_holiday"):
                    employees_map[emp][safe_day_key] = make_day_cell(
                        day_off_info.get("status", "WEEKEND"),
                        "",
                        "",
                        "",
                        0,
                        day_off_info.get("label", "")
                    )
                else:
                    employees_map[emp][safe_day_key] = make_day_cell("ABSENT", "", "", "", 0, "")

    # -----------------------------------------------------------------------------
    # Aggregate / Result
    # -----------------------------------------------------------------------------
    result = []

    summary_employees_count = 0
    summary_total_actual_work_hours = 0.0
    summary_total_leave_hours = 0.0
    summary_total_work_with_leave = 0.0
    summary_total_expected_hours = 0.0
    summary_total_unjustified_hours = 0.0
    summary_total_late_entry_minutes = 0.0

    summary_present_days = 0
    summary_wfh_days = 0
    summary_leave_days = 0
    summary_absent_days = 0
    summary_weekend_days = 0
    summary_holiday_days = 0

    employees_with_unjustified_hours_count = 0
    employees_with_absence_count = 0

    top_actual_hours_items = []
    top_unjustified_hours_items = []
    top_late_entry_items = []

    department_actual_hours_map = {}
    department_unjustified_hours_map = {}

    daily_trend_map = {}
    for dt in date_list:
        daily_trend_map[dt] = {
            "label": dt,
            "present": 0,
            "wfh": 0,
            "leave": 0,
            "absent": 0,
            "weekend": 0,
            "holiday": 0
        }

    for emp in employees_map:
        row = employees_map[emp]

        actual_work_hours = 0.0
        leave_hours = 0.0
        expected_hours = 0.0
        total_late_entry_minutes = 0.0

        emp_present_days = 0
        emp_wfh_days = 0
        emp_leave_days = 0
        emp_absent_days = 0
        emp_weekend_days = 0
        emp_holiday_days = 0

        matched_any_day = 0

        for dt in date_list:
            if not day_matches_shift_filter(emp, dt):
                continue

            cell = row.get(date_field_map[dt], "")
            if not cell:
                continue

            parts = str(cell).split("|")
            status = parts[0] if len(parts) > 0 else ""
            cell_hours = float(parts[1]) if len(parts) > 1 and parts[1] not in [None, ""] else 0.0
            late_minutes = float(parts[4]) if len(parts) > 4 and parts[4] not in [None, ""] else 0.0

            if selected_status_drilldown and status != selected_status_drilldown:
                row[date_field_map[dt]] = ""
                continue

            matched_any_day = 1

            day_expected_hours = get_expected_hours(emp, dt)

            if day_expected_hours > 0:
                expected_hours = expected_hours + day_expected_hours

            if status == "PRESENT":
                actual_work_hours = actual_work_hours + cell_hours
                total_late_entry_minutes = total_late_entry_minutes + late_minutes
                emp_present_days = emp_present_days + 1
                daily_trend_map[dt]["present"] = daily_trend_map[dt]["present"] + 1

            elif status == "WFH":
                actual_work_hours = actual_work_hours + cell_hours
                emp_wfh_days = emp_wfh_days + 1
                daily_trend_map[dt]["wfh"] = daily_trend_map[dt]["wfh"] + 1

            elif status == "LEAVE":
                leave_hours = leave_hours + day_expected_hours
                emp_leave_days = emp_leave_days + 1
                daily_trend_map[dt]["leave"] = daily_trend_map[dt]["leave"] + 1

            elif status == "ABSENT":
                emp_absent_days = emp_absent_days + 1
                daily_trend_map[dt]["absent"] = daily_trend_map[dt]["absent"] + 1

            elif status == "WEEKEND":
                emp_weekend_days = emp_weekend_days + 1
                daily_trend_map[dt]["weekend"] = daily_trend_map[dt]["weekend"] + 1

            elif status == "HOLIDAY":
                emp_holiday_days = emp_holiday_days + 1
                daily_trend_map[dt]["holiday"] = daily_trend_map[dt]["holiday"] + 1

            else:
                emp_absent_days = emp_absent_days + 1
                daily_trend_map[dt]["absent"] = daily_trend_map[dt]["absent"] + 1

        if (selected_status_drilldown or shift_type_filter) and not matched_any_day:
            continue

        work_with_leave = actual_work_hours + leave_hours
        unjustified_hours = expected_hours - work_with_leave

        if unjustified_hours < 0:
            unjustified_hours = 0

        actual_work_hours = round2(actual_work_hours)
        leave_hours = round2(leave_hours)
        work_with_leave = round2(work_with_leave)
        expected_hours = round2(expected_hours)
        unjustified_hours = round2(unjustified_hours)
        total_late_entry_minutes = round2(total_late_entry_minutes)
        late_entry_hours = round2(total_late_entry_minutes / 60.0)

        row["actual_work_hours"] = actual_work_hours
        row["leave_hours"] = leave_hours
        row["work_with_leave"] = work_with_leave
        row["expected_hours"] = expected_hours
        row["unjustified_hours"] = unjustified_hours
        row["late_entry_hours"] = late_entry_hours

        row["present_days"] = emp_present_days
        row["wfh_days"] = emp_wfh_days
        row["leave_days"] = emp_leave_days
        row["absent_days"] = emp_absent_days
        row["weekend_days"] = emp_weekend_days
        row["holiday_days"] = emp_holiday_days

        result.append(row)

        summary_employees_count = summary_employees_count + 1
        summary_total_actual_work_hours = summary_total_actual_work_hours + actual_work_hours
        summary_total_leave_hours = summary_total_leave_hours + leave_hours
        summary_total_work_with_leave = summary_total_work_with_leave + work_with_leave
        summary_total_expected_hours = summary_total_expected_hours + expected_hours
        summary_total_unjustified_hours = summary_total_unjustified_hours + unjustified_hours
        summary_total_late_entry_minutes = summary_total_late_entry_minutes + total_late_entry_minutes

        summary_present_days = summary_present_days + emp_present_days
        summary_wfh_days = summary_wfh_days + emp_wfh_days
        summary_leave_days = summary_leave_days + emp_leave_days
        summary_absent_days = summary_absent_days + emp_absent_days
        summary_weekend_days = summary_weekend_days + emp_weekend_days
        summary_holiday_days = summary_holiday_days + emp_holiday_days

        if unjustified_hours > 0:
            employees_with_unjustified_hours_count = employees_with_unjustified_hours_count + 1

        if emp_absent_days > 0:
            employees_with_absence_count = employees_with_absence_count + 1

        emp_name_label = row.get("employee_name") or row.get("employee") or ""
        dept_label = row.get("department") or "No Department"

        top_actual_hours_items.append({
            "label": emp_name_label,
            "value": actual_work_hours
        })

        top_unjustified_hours_items.append({
            "label": emp_name_label,
            "value": unjustified_hours
        })

        top_late_entry_items.append({
            "label": emp_name_label,
            "value": late_entry_hours
        })

        if dept_label not in department_actual_hours_map:
            department_actual_hours_map[dept_label] = 0.0
        department_actual_hours_map[dept_label] = department_actual_hours_map[dept_label] + actual_work_hours

        if dept_label not in department_unjustified_hours_map:
            department_unjustified_hours_map[dept_label] = 0.0
        department_unjustified_hours_map[dept_label] = department_unjustified_hours_map[dept_label] + unjustified_hours

    summary_total_actual_work_hours = round2(summary_total_actual_work_hours)
    summary_total_leave_hours = round2(summary_total_leave_hours)
    summary_total_work_with_leave = round2(summary_total_work_with_leave)
    summary_total_expected_hours = round2(summary_total_expected_hours)
    summary_total_unjustified_hours = round2(summary_total_unjustified_hours)
    summary_total_late_entry_minutes = round2(summary_total_late_entry_minutes)
    summary_total_late_entry_hours = round2(summary_total_late_entry_minutes / 60.0)

    compliance_rate = 0.0
    if summary_total_expected_hours > 0:
        compliance_rate = round2((summary_total_work_with_leave / summary_total_expected_hours) * 100.0)

    highest_unjustified_employee_name = ""
    highest_unjustified_employee_value = 0.0

    sorted_unjustified = sorted(top_unjustified_hours_items, key=lambda x: float(x.get("value") or 0), reverse=True)
    if len(sorted_unjustified) > 0:
        highest_unjustified_employee_name = sorted_unjustified[0].get("label") or ""
        highest_unjustified_employee_value = round2(sorted_unjustified[0].get("value") or 0)

    summary = {
        "filters": {
            "from_date": from_date,
            "to_date": to_date,
            "employee": employee,
            "company": company,
            "branch": branch,
            "department": department,
            "designation": designation,
            "gender": gender,
            "shift_type": shift_type_filter,
            "drilldown_dimension": resolved_drilldown_dimension,
            "drilldown_value": resolved_drilldown_value,
            "drilldown_source": drilldown_source
        },
        "operational": {
            "employees_count": summary_employees_count,
            "total_expected_hours": summary_total_expected_hours,
            "total_actual_work_hours": summary_total_actual_work_hours,
            "total_leave_hours": summary_total_leave_hours,
            "total_late_entry_hours": summary_total_late_entry_hours
        },
        "control": {
            "total_unjustified_hours": summary_total_unjustified_hours,
            "compliance_rate": compliance_rate,
            "employees_with_unjustified_hours_count": employees_with_unjustified_hours_count,
            "employees_with_absence_count": employees_with_absence_count,
            "highest_unjustified_employee_name": highest_unjustified_employee_name,
            "highest_unjustified_employee_value": highest_unjustified_employee_value
        }
