def norm(v):
    if v is None:
        return None
    v = str(v).strip()
    if (not v) or (v.lower() in ("null", "none", "undefined", "nan")):
        return None
    return v

def norm_key(v, default_value="Unspecified"):
    v = norm(v)
    return v or default_value

def safe_date(v):
    v = norm(v)
    if not v:
        return None
    try:
        return frappe.utils.getdate(v)
    except Exception:
        return None

def safe_datetime(v):
    v = norm(v)
    if not v:
        return None
    try:
        return frappe.utils.get_datetime(v)
    except Exception:
        return None

def to_bool(v):
    if v in (1, "1", True, "true", "True", "yes", "Yes"):
        return True
    if isinstance(v, str):
        return v.strip().lower() in ("1", "true", "yes", "y")
    return False

def inc(d, key, step=1):
    d[key] = d.get(key, 0) + step

def date_in_range(dt, from_dt, to_dt):
    if not dt:
        return False
    d = frappe.utils.getdate(dt)
    if from_dt and d < from_dt:
        return False
    if to_dt and d > to_dt:
        return False
    return True

def month_key(dt):
    return str(dt.year) + "-" + str(dt.month).zfill(2)

def month_label(dt):
    months_en = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    return months_en[dt.month - 1] + " " + str(dt.year)

def day_key(dt):
    return str(dt.year) + "-" + str(dt.month).zfill(2) + "-" + str(dt.day).zfill(2)

def build_day_range(from_dt, to_dt):
    out = []
    cur = from_dt
    while cur <= to_dt:
        out.append({
            "key": day_key(cur),
            "label": str(cur)
        })
        cur = frappe.utils.add_days(cur, 1)
    return out

def build_month_range(from_dt, to_dt):
    out = []
    y = from_dt.year
    m = from_dt.month

    while (y < to_dt.year) or (y == to_dt.year and m <= to_dt.month):
        dt = frappe.utils.getdate(str(y) + "-" + str(m).zfill(2) + "-01")
        out.append({
            "key": month_key(dt),
            "label": month_label(dt)
        })
        m = m + 1
        if m > 12:
            m = 1
            y = y + 1

    return out

def normalize_gender(v):
    v = norm(v)
    if not v:
        return "Unspecified"

    x = v.lower()
    if x in ["male", "m", "ذكر", "رجل", "man"]:
        return "Male"
    if x in ["female", "f", "أنثى", "انثى", "امرأة", "امراة", "woman"]:
        return "Female"
    return v

def sort_dict_payload(d, label_key="label", value_key="value", keep_zero=False):
    items = []
    for k in d:
        v = d.get(k, 0)
        if (not keep_zero) and (not v):
            continue
        items.append({
            label_key: k,
            value_key: v
        })
    items.sort(key=lambda x: x.get(value_key, 0), reverse=True)
    return items

def top_n_payload(d, n, label_key="label", value_key="value"):
    return sort_dict_payload(d, label_key, value_key, False)[:n]

def avg_from_list(values):
    clean = []
    for v in values:
        try:
            if v is not None:
                clean.append(float(v))
        except Exception:
            pass
    if not clean:
        return None
    return round(sum(clean) / len(clean), 2)


