def norm(v):
    if v is None:
        return None
    v = str(v).strip()
    if (not v) or (v.lower() in ("null", "none", "undefined", "nan")):
        return None
    return v

def norm_key(v, default_value="Unspecified"):
    v = norm(v)
    if v:
        return v
    return default_value

def safe_date(v):
    v = norm(v)
    if not v:
        return None
    try:
        return frappe.utils.getdate(v)
    except Exception:
        return None

def inc(d, key, step):
    d[key] = d.get(key, 0) + step

def start_of_year(dt):
    return frappe.utils.getdate(str(dt.year) + "-01-01")

def end_of_year(dt):
    return frappe.utils.getdate(str(dt.year) + "-12-31")

def quarter_bounds(dt):
    if dt.month in (1, 2, 3):
        return [
            frappe.utils.getdate(str(dt.year) + "-01-01"),
            frappe.utils.getdate(str(dt.year) + "-03-31")
        ]
    if dt.month in (4, 5, 6):
        return [
            frappe.utils.getdate(str(dt.year) + "-04-01"),
            frappe.utils.getdate(str(dt.year) + "-06-30")
        ]
    if dt.month in (7, 8, 9):
        return [
            frappe.utils.getdate(str(dt.year) + "-07-01"),
            frappe.utils.getdate(str(dt.year) + "-09-30")
        ]
    return [
        frappe.utils.getdate(str(dt.year) + "-10-01"),
        frappe.utils.getdate(str(dt.year) + "-12-31")
    ]

def date_in_range(dt, from_dt, to_dt):
    if not dt:
        return False
    if from_dt and dt < from_dt:
        return False
    if to_dt and dt > to_dt:
        return False
    return True

def month_key(dt):
    return str(dt.year) + "-" + str(dt.month).zfill(2)

def month_label(dt):
    months_en = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun",
        "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    ]
    return months_en[dt.month - 1] + " " + str(dt.year)

def build_month_range(from_dt, to_dt):
    out = []
    y = from_dt.year
    m = from_dt.month

    while (y < to_dt.year) or (y == to_dt.year and m <= to_dt.month):
        dt = frappe.utils.getdate(str(y) + "-" + str(m).zfill(2) + "-01")
        out.append({
            "key": month_key(dt),
            "label": month_label(dt)
        })
        m = m + 1
        if m > 12:
            m = 1
            y = y + 1

    return out

def normalize_gender(v):
    v = norm(v)
    if not v:
        return "Unspecified"

    x = v.lower()

    male_vals = ["male", "m", "ذكر", "رجل", "man"]
    female_vals = ["female", "f", "أنثى", "انثى", "امرأة", "امراة", "woman"]

    if x in male_vals:
        return "Male"
    if x in female_vals:
        return "Female"

    return v

def get_age(dob, today_dt):
    dob_dt = safe_date(dob)
    if not dob_dt:
        return None

    age = today_dt.year - dob_dt.year
    if (today_dt.month, today_dt.day) < (dob_dt.month, dob_dt.day):
        age = age - 1

    if age < 0:
        return None
    return age

def age_bucket(age):
    if age is None:
        return "Unspecified"
    if age < 15:
        return "<15"
    if age <= 19:
        return "15-19"
    if age <= 24:
        return "20-24"
    if age <= 29:
        return "25-29"
    if age <= 34:
        return "30-34"
    if age <= 39:
        return "35-39"
    if age <= 44:
        return "40-44"
    if age <= 49:
        return "45-49"
    if age <= 54:
        return "50-54"
    if age <= 59:
        return "55-59"
    if age <= 64:
        return "60-64"
    if age <= 69:
        return "65-69"
    if age <= 74:
        return "70-74"
    if age <= 79:
        return "75-79"
    return "80+"

def sort_dict_payload(d, label_key, value_key, keep_zero):
    items = []
    for k in d:
        v = d.get(k, 0)
        if (not keep_zero) and (not v):
            continue
        items.append({
            label_key: k,
            value_key: v
        })
    items.sort(key=lambda x: x.get(value_key, 0), reverse=True)
    return items

def top_n_payload(d, n, label_key, value_key):
    items = sort_dict_payload(d, label_key, value_key, False)
    return items[:n]

def add_months(dt, months):
    y = dt.year + ((dt.month - 1 + months) // 12)
    m = ((dt.month - 1 + months) % 12) + 1

    month_days = {
        1: 31,
        2: 29 if ((y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)) else 28,
        3: 31,
        4: 30,
        5: 31,
        6: 30,
        7: 31,
        8: 31,
        9: 30,
        10: 31,
        11: 30,
        12: 31
    }

    d = dt.day
    if d > month_days[m]:
        d = month_days[m]

    return frappe.utils.getdate(str(y) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2))

def is_retiring_within_3_months(retirement_date, today_dt, three_months_later_dt):
    if not retirement_date:
        return False
    return retirement_date >= today_dt and retirement_date <= three_months_later_dt

def is_contract_ending_within_1_month(contract_end, today_dt, one_month_later_dt):
    if not contract_end:
        return False
    return contract_end >= today_dt and contract_end <= one_month_later_dt

