def norm(v):
    if v is None:
        return None
    v = str(v).strip()
    if v == "" or v.lower() in ("null", "none", "undefined"):
        return None
    return v

def parse_assign(raw):
    """Return list of assigned user IDs from _assign JSON, safely."""
    if not raw:
        return []
    try:
        arr = json.loads(raw) if isinstance(raw, str) else raw
        if isinstance(arr, list):
            out = []
            for u in arr:
                if isinstance(u, str) and u.strip():
                    out.append(u)
            return out
        return []
    except Exception:
        return []

def as_weight(v):
    """If weight is null/empty/invalid -> 1"""
    if v is None:
        return 1
    try:
        vv = float(v)
        if vv > 0:
            return vv
        return 1
    except Exception:
        return 1

def as_progress(v):
    """Normalize progress into float 0..100"""
    if v is None or v == "":
        return 0.0
    try:
        vv = float(v)
        if vv < 0:
            return 0.0
        if vv > 100:
            return 100.0
        return vv
    except Exception:
        return 0.0

DONE_STATUSES = set(["Done", "Completed"])

# =========================
# Completion calculations
# =========================
def calc_task_completion(leaves):
    """
    % = completed leaves / total leaves * 100
    """
    if not leaves:
        return 0.0

    done_count = 0
    total_count = 0

    for l in leaves:
        total_count = total_count + 1
        st = (l.get("status") or "").strip()
        if st in DONE_STATUSES:
            done_count = done_count + 1

    if total_count == 0:
        return 0.0

    return (done_count * 100.0) / total_count

def calc_task_progress(leaves):
    """
    % = average of leaf.progress
    """
    if not leaves:
        return 0.0

    total = 0.0
    count = 0

    for l in leaves:
        total = total + as_progress(l.get("progress"))
        count = count + 1

    if count == 0:
        return 0.0

    return total / count

def calc_task_weight(leaves):
    """
    % = done weight / total weight * 100
    """
    if not leaves:
        return 0.0

    total_weight = 0.0
    done_weight = 0.0

    for l in leaves:
        w = as_weight(l.get("task_weight"))
        total_weight = total_weight + w

        st = (l.get("status") or "").strip()
        if st in DONE_STATUSES:
            done_weight = done_weight + w

    if total_weight <= 0:
        return 0.0

    return (done_weight / total_weight) * 100.0
# Task Completion = عدد المهام المنجزة ÷ إجمالي المهام
# Task Progress = متوسط حقل progress
# Task Weight = وزن المهام المنجزة ÷ إجمالي الأوزان
def calculate_progress(leaves, method):
    method = (method or "Task Completion").strip()

    if method == "Task Progress":
        return round(calc_task_progress(leaves), 2)
    elif method == "Task Weight":
        return round(calc_task_weight(leaves), 2)
    else:
        return round(calc_task_completion(leaves), 2)

