def format_hours_short(value):
    total_minutes = int(round(float(value or 0) * 60))
    hours = int(total_minutes // 60)
    minutes = int(total_minutes % 60)

    if total_minutes <= 0:
        return "0m"

    if hours > 0 and minutes > 0:
        return str(hours) + "h " + str(minutes) + "m"

    if hours > 0:
        return str(hours) + "h"

    return str(minutes) + "m"

def format_hours_day_short(value, day_hours):
    total_minutes = int(round(float(value or 0) * 60))
    day_minutes = int(round(float(day_hours or 0) * 60))

    if total_minutes <= 0:
        return "0m"

    if day_minutes <= 0:
        return format_hours_short(value)

    days = int(total_minutes // day_minutes)
    remaining_minutes = int(total_minutes % day_minutes)

    hours = int(remaining_minutes // 60)
    minutes = int(remaining_minutes % 60)

    parts = []

    if days > 0:
        parts.append(str(days) + "D")

    if hours > 0:
        parts.append(str(hours) + "h")

    if minutes > 0:
        parts.append(str(minutes) + "m")

    if not parts:
        return "0m"

    return " ".join(parts)

