def add_hours_to_datetime(start_dt, hours_value):
    if not start_dt:
        return None

    hrs = float(hours_value or 0)
    if hrs <= 0:
        return None

    return frappe.utils.add_to_date(
        start_dt,
        hours=hrs,
        as_datetime=True
    )

def diff_minutes(start_dt, end_dt):
    if not start_dt or not end_dt:
        return 0.0

    start_dt = start_dt.replace(second=0, microsecond=0)
    end_dt = end_dt.replace(second=0, microsecond=0)

    seconds = (end_dt - start_dt).total_seconds()
    if seconds <= 0:
        return 0.0

    return float(int(seconds // 60))

def diff_hours(start_dt, end_dt):
    if not start_dt or not end_dt:
        return 0.0

    total_minutes = diff_minutes(start_dt, end_dt)
    return round2(total_minutes / 60.0)

