def get_shift_start_end_datetimes(shift_doc, dt):
    if not shift_doc:
        return [None, None]

    shift_start_dt = combine_date_and_time(dt, shift_doc.start_time)
    shift_end_dt = combine_date_and_time(dt, shift_doc.end_time)

    if shift_start_dt and shift_end_dt and shift_end_dt < shift_start_dt:
        shift_end_dt = frappe.utils.add_to_date(shift_end_dt, days=1, as_datetime=True)

    return [shift_start_dt, shift_end_dt]

