def make_interval(start_dt, end_dt, label):
    if not start_dt or not end_dt:
        return None
    if end_dt <= start_dt:
        return None
    return {
        "start": start_dt,
        "end": end_dt,
        "label": label or ""
    }

def merge_intervals(intervals):
    clean = []
    for it in intervals:
        if it and it.get("start") and it.get("end") and it.get("end") > it.get("start"):
            clean.append(it)

    sorted_intervals = sorted(clean, key=lambda x: x.get("start"))

    merged = []
    for it in sorted_intervals:
        if not merged:
            merged.append({
                "start": it.get("start"),
                "end": it.get("end"),
                "labels": [it.get("label") or ""]
            })
        else:
            last = merged[-1]
            if it.get("start") <= last.get("end"):
                if it.get("end") > last.get("end"):
                    last["end"] = it.get("end")
                lbls = last.get("labels") or []
                lbls.append(it.get("label") or "")
                last["labels"] = lbls
            else:
                merged.append({
                    "start": it.get("start"),
                    "end": it.get("end"),
                    "labels": [it.get("label") or ""]
                })

    return merged

def interval_minutes_total(intervals):
    merged = merge_intervals(intervals)
    total_minutes = 0.0
    for it in merged:
        total_minutes = total_minutes + diff_minutes(it.get("start"), it.get("end"))
    return total_minutes

def overlap_minutes(start_a, end_a, start_b, end_b):
    if not start_a or not end_a or not start_b or not end_b:
        return 0.0

    overlap_start = start_a
    if start_b > overlap_start:
        overlap_start = start_b

    overlap_end = end_a
    if end_b < overlap_end:
        overlap_end = end_b

    if overlap_end <= overlap_start:
        return 0.0

    return diff_minutes(overlap_start, overlap_end)

def intervals_overlap_minutes(intervals, start_dt, end_dt):
    total = 0.0
    for it in merge_intervals(intervals):
        total = total + overlap_minutes(it.get("start"), it.get("end"), start_dt, end_dt)
    return total

def intervals_outside_shift_minutes(intervals, shift_start_dt, shift_end_dt):
    total = 0.0

    for it in merge_intervals(intervals):
        interval_total = diff_minutes(it.get("start"), it.get("end"))
        inside_total = overlap_minutes(it.get("start"), it.get("end"), shift_start_dt, shift_end_dt)
        outside_total = interval_total - inside_total
        if outside_total > 0:
            total = total + outside_total

    return total

