    # -------------------------------------------------------------------------
    # Employee Checkin query
    # -------------------------------------------------------------------------
    checkin_rows = []
    if employee_list:
        checkin_rows = frappe.get_all(
            "Employee Checkin",
            filters={
                "employee": ["in", employee_list],
