            },
            fields=["name", "employee", "time", "log_type", "custom_over_night"],
            order_by="employee asc, time asc"
        )

    # Keep raw checkins first. We build checkin_day_map after shifts are loaded,
    # so duplicate IN/OUT at the exact same timestamp can be resolved using shift time.
    raw_checkin_day_map = {}
    checkin_day_map = {}

    for row in checkin_rows:
        emp = row.employee
        dt = str(frappe.utils.getdate(row.time))
        key = str(emp) + "||" + dt

        if key not in raw_checkin_day_map:
            raw_checkin_day_map[key] = []

        raw_checkin_day_map[key].append(row)


    # -------------------------------------------------------------------------
    # Shift Assignment query
    # -------------------------------------------------------------------------
    assignment_filters = {
        "start_date": ["<=", to_date]
    }

    if employee_list:
        assignment_filters["employee"] = ["in", employee_list]

    shift_assignments = frappe.get_all(
        "Shift Assignment",
        filters=assignment_filters,
        fields=["employee", "shift_type", "start_date", "end_date"],
        order_by="employee asc, start_date asc"
    )

    employee_date_shift_map = {}

    for sa in shift_assignments:
        if not sa.employee or not sa.shift_type or not sa.start_date:
            continue

        assignment_start = frappe.utils.getdate(sa.start_date)
        assignment_end = frappe.utils.getdate(sa.end_date) if sa.end_date else frappe.utils.getdate(to_date)

        if assignment_start < from_date_obj:
            assignment_start = from_date_obj

        if assignment_end > to_date_obj:
            assignment_end = to_date_obj

        if assignment_start > assignment_end:
            continue

        if sa.shift_type not in shift_seen:
            shift_names.append(sa.shift_type)
            shift_seen[sa.shift_type] = 1

        d = assignment_start
        while d <= assignment_end:
            employee_date_shift_map[str(sa.employee) + "||" + str(d)] = sa.shift_type
            d = frappe.utils.add_days(d, 1)

    # -------------------------------------------------------------------------
    # Shift Type query
    # -------------------------------------------------------------------------
    shift_map = {}
    holiday_list_names = []
