        employee_rows = filtered_employee_rows
        employee_list = filtered_employee_list

        employee_details_map = {}
        for er in employee_rows:
            employee_details_map[er.name] = er


    # -------------------------------------------------------------------------
    # Build Employee Checkin day map
    # Resolve duplicate IN/OUT at the exact same timestamp using shift boundary
    # -------------------------------------------------------------------------
    checkin_day_map = {}

    for key in raw_checkin_day_map:
        key_parts = str(key).split("||")
        emp_for_checkin = key_parts[0]
        dt_for_checkin = key_parts[1] if len(key_parts) > 1 else ""

        shift_name_for_checkin = get_effective_shift(
