            shift_start_dt_for_checkin = shift_range_for_checkin[0]
            shift_end_dt_for_checkin = shift_range_for_checkin[1]

        rows_for_day = raw_checkin_day_map.get(key) or []

        grouped_by_time = {}
        for row in rows_for_day:
            row_time_key = str(row.time)
            if row_time_key not in grouped_by_time:
                grouped_by_time[row_time_key] = []
            grouped_by_time[row_time_key].append(row)

        checkin_day_map[key] = {
            "first_in": None,
            "last_out": None,
            "last_out_custom_over_night": 0.0
        }

        for row_time_key in grouped_by_time:
            same_time_rows = grouped_by_time.get(row_time_key) or []

            has_in = False
            has_out = False
            selected_row = same_time_rows[0] if same_time_rows else None

            if not selected_row:
                continue

            for same_row in same_time_rows:
                log_type_value = str(same_row.log_type or "").strip().upper()

                if log_type_value == "IN":
                    has_in = True

                elif log_type_value == "OUT":
                    has_out = True
                    selected_row = same_row

            final_log_type = str(selected_row.log_type or "").strip().upper()

            # If the same timestamp exists as IN and OUT, keep only one.
            # If it is closer to shift end, treat it as OUT.
            # If it is closer to shift start, treat it as IN.
            if has_in and has_out and shift_start_dt_for_checkin and shift_end_dt_for_checkin:
                selected_time = frappe.utils.get_datetime(selected_row.time)

                minutes_from_start = abs(
                    (selected_time - shift_start_dt_for_checkin).total_seconds() / 60.0
                )

                minutes_from_end = abs(
                    (selected_time - shift_end_dt_for_checkin).total_seconds() / 60.0
                )

                if minutes_from_end < minutes_from_start:
                    final_log_type = "OUT"
                else:
                    final_log_type = "IN"

            row_time = selected_row.time
            item = checkin_day_map[key]

            if final_log_type == "IN":
                if (not item["first_in"]) or row_time < item["first_in"]:
                    item["first_in"] = row_time

            elif final_log_type == "OUT":
                if (not item["last_out"]) or row_time > item["last_out"]:
                    item["last_out"] = row_time
                    item["last_out_custom_over_night"] = float(selected_row.custom_over_night or 0)

