            if holiday_list_name:
                holiday_row = holiday_map.get(str(holiday_list_name) + "||" + str(dt))
                if holiday_row:
                    weekday = frappe.utils.getdate(dt).weekday()

                    if weekday in [4, 5]:
                        return {
                            "is_holiday": 1,
                            "status": "WEEKEND",
                            "label": "Weekend"
                        }

                    return {
                        "is_holiday": 1,
                        "status": "HOLIDAY",
                        "label": holiday_row.get("description") or "Holiday"
                    }

        weekday = frappe.utils.getdate(dt).weekday()
        if weekday in [4, 5]:
            return {
                "is_holiday": 1,
                "status": "WEEKEND",
                "label": "Weekend"
            }

        return {
            "is_holiday": 0,
