        day_key = str(row.attendance_date)
        key = str(row.employee) + "||" + day_key

        hours = round2(row.hours or 0)
        if hours <= 0:
            continue

        is_hourly = 1 if row.is_hourly else 0
        start_dt = None
        end_dt = None

        if is_hourly:
            if not row.from_time:
                # Hourly activity without start time cannot be converted into an interval.
                # It will still be counted as fallback hours below.
                is_hourly = 0
            else:
                start_dt = combine_date_and_time(day_key, row.from_time)
                end_dt = add_hours_to_datetime(start_dt, hours)

                if not start_dt or not end_dt:
