        )
    # -------------------------------------------------------------------------
    # Build employee/day matrix
    # -------------------------------------------------------------------------
    employees_map = {}

    for emp in employee_list:
        emp_details = employee_details_map.get(emp, {})

        base_row = {
            "employee": emp or "",
            "employee_name": emp_details.get("employee_name") or "",
            "company": emp_details.get("company") or "",
            "branch": emp_details.get("branch") or "",
            "department": emp_details.get("department") or "",
            "designation": emp_details.get("designation") or "",
            "gender": emp_details.get("gender") or ""
        }

        for dt in date_list:
            safe_dt = date_field_map[dt]

            if not day_matches_shift_filter(emp, dt):
                base_row[safe_dt] = ""
                base_row[safe_dt + "_leave_hours"] = 0.0
                base_row[safe_dt + "_overtime_hours"] = 0.0
                base_row[safe_dt + "_early_exit_minutes"] = 0.0
                continue

            day_off_info = get_day_off_info(emp, dt)
            expected_day_hours = get_expected_hours(emp, dt)

            key = str(emp) + "||" + str(dt)

            day_checkin = checkin_day_map.get(key, {})
            day_exception = exception_map.get(key, {})
            day_leave = leave_day_map.get(key, {"hours": 0.0, "items": []})
            day_non_onsite = non_onsite_map.get(key)

            if selected_exception_type_drilldown:
                matched_exception = 0
                for exi in day_exception.get("items", []):
                    ex_type_value = str(exi.get("type") or "").strip()
                    selected_value = str(selected_exception_type_drilldown).strip()
                    if ex_type_value == selected_value:
                        matched_exception = 1
                        break

                if not matched_exception:
                    base_row[safe_dt] = ""
                    base_row[safe_dt + "_leave_hours"] = 0.0
                    base_row[safe_dt + "_overtime_hours"] = 0.0
                    base_row[safe_dt + "_early_exit_minutes"] = 0.0
                    continue

            first_in_dt = day_checkin.get("first_in")
            last_out_dt = day_checkin.get("last_out")

            manual_in_dt = combine_date_and_time(dt, day_exception.get("manual_check_in"))
            manual_out_dt = combine_date_and_time(dt, day_exception.get("manual_check_out"))

            used_manual_in = False
            used_manual_out = False

            if (not first_in_dt) and manual_in_dt:
                first_in_dt = manual_in_dt
                used_manual_in = True

            if (not last_out_dt) and manual_out_dt:
                last_out_dt = manual_out_dt
                used_manual_out = True

            leave_hours = round2(day_leave.get("hours") or 0)

            if day_off_info.get("is_holiday") and (not first_in_dt) and (not last_out_dt) and (not day_non_onsite) and leave_hours <= 0:
                if day_off_info.get("status") == "WEEKEND":
                    base_row[safe_dt] = make_day_cell("WEEKEND", "Weekend", "", "", "", "", "", 0, 0)
                else:
                    holiday_name = day_off_info.get("label") or "Holiday"
                    base_row[safe_dt] = make_day_cell("HOLIDAY", "Holiday", holiday_name, "", "", "", "", 0, 0)

                base_row[safe_dt + "_leave_hours"] = 0.0
                base_row[safe_dt + "_overtime_hours"] = 0.0
                base_row[safe_dt + "_early_exit_minutes"] = 0.0
                continue

            # -----------------------------------------------------------------
            # Build work intervals: Checkin + hourly WFH/DUTY
            # -----------------------------------------------------------------
            work_intervals = []
            activity_lines = []
            fallback_non_onsite_hours = 0.0
            main_non_onsite_status = ""
            main_non_onsite_label = ""

            if first_in_dt and last_out_dt:
                work_intervals.append(make_interval(first_in_dt, last_out_dt, "Checkin"))

            if day_non_onsite:
                for ni in day_non_onsite.get("items") or []:
                    status_code = ni.get("status_code") or ""
                    label = ni.get("label") or ""
                    hours = round2(ni.get("hours") or 0)

                    if not main_non_onsite_status:
                        main_non_onsite_status = status_code
                        main_non_onsite_label = label

                    if ni.get("is_hourly") and ni.get("start_dt") and ni.get("end_dt"):
                        work_intervals.append(make_interval(ni.get("start_dt"), ni.get("end_dt"), status_code))
                        activity_lines.append(label + " " + format_hours_short(hours) + " " + format_hhmm(ni.get("start_dt")) + " -> " + format_hhmm(ni.get("end_dt")))
                    else:
                        fallback_non_onsite_hours = fallback_non_onsite_hours + hours
                        activity_lines.append(label + " " + format_hours_short(hours))

            # Onsite or mixed
            if first_in_dt or last_out_dt:
                in_txt = format_hhmm(first_in_dt) if first_in_dt else "?"
                out_txt = format_hhmm(last_out_dt) if last_out_dt else "?"

                if first_in_dt:
                    in_txt = in_txt + " (" + ("M" if used_manual_in else "A") + ")"
                if last_out_dt:
                    out_txt = out_txt + " (" + ("M" if used_manual_out else "A") + ")"

                line_2 = in_txt + " -> " + out_txt

                day_custom_over_night_minutes = float(day_checkin.get("last_out_custom_over_night") or 0)
                day_custom_over_night_hours = round2(day_custom_over_night_minutes / 60.0)

                merged_minutes = interval_minutes_total(work_intervals)
                actual_work_hours = round2(merged_minutes / 60.0)

                if day_custom_over_night_hours > 0:
                    actual_work_hours = actual_work_hours + day_custom_over_night_hours

                if fallback_non_onsite_hours > 0:
                    actual_work_hours = actual_work_hours + fallback_non_onsite_hours

                actual_work_hours = actual_work_hours - leave_hours
                if actual_work_hours < 0:
                    actual_work_hours = 0.0

                shift_name = get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift)
                shift_doc = shift_map.get(shift_name) if shift_name else None

                raw_late_minutes = 0.0
                effective_late_minutes = 0.0
                raw_early_exit_minutes = 0.0
                effective_early_exit_minutes = 0.0
                overtime_hours = 0.0

                shift_start_dt = None
                shift_end_dt = None
                grace_in = 0.0
                grace_out = 0.0

                if shift_doc:
                    shift_range = get_shift_start_end_datetimes(shift_doc, dt)
                    shift_start_dt = shift_range[0]
                    shift_end_dt = shift_range[1]

                    grace_in = get_late_grace_minutes(shift_doc)
                    grace_out = get_early_exit_grace_minutes(shift_doc)

                    if first_in_dt and shift_start_dt:
                        grace_in_dt = add_minutes(shift_start_dt, grace_in)
                        raw_late_minutes = diff_minutes(grace_in_dt, first_in_dt)

                        if raw_late_minutes < 0:
                            raw_late_minutes = 0.0

                        covered_late_minutes = intervals_overlap_minutes(work_intervals, grace_in_dt, first_in_dt)
                        raw_late_minutes = raw_late_minutes - covered_late_minutes
                        if raw_late_minutes < 0:
                            raw_late_minutes = 0.0

                    waived_late = round2(day_exception.get("waive_late_minutes") or 0)
                    effective_late_minutes = raw_late_minutes - waived_late
                    if effective_late_minutes < 0:
                        effective_late_minutes = 0.0

                    if last_out_dt and shift_end_dt:
                        early_cutoff_dt = add_minutes(shift_end_dt, 0 - grace_out)
                        raw_early_exit_minutes = diff_minutes(last_out_dt, early_cutoff_dt)

                        if raw_early_exit_minutes < 0:
                            raw_early_exit_minutes = 0.0

                        covered_early_minutes = intervals_overlap_minutes(work_intervals, last_out_dt, early_cutoff_dt)
                        raw_early_exit_minutes = raw_early_exit_minutes - covered_early_minutes
                        if raw_early_exit_minutes < 0:
                            raw_early_exit_minutes = 0.0

                        waived_early = round2(day_exception.get("waive_early_exit_minutes") or 0)
                        effective_early_exit_minutes = raw_early_exit_minutes - waived_early
                        if effective_early_exit_minutes < 0:
                            effective_early_exit_minutes = 0.0

                    if shift_start_dt and shift_end_dt:
                        overtime_minutes = intervals_outside_shift_minutes(work_intervals, shift_start_dt, shift_end_dt)
                        overtime_hours = round2(overtime_minutes / 60.0)

                top_value = format_hours_short(actual_work_hours)
                line_3 = ""
                line_4 = ""
                line_5 = ""
                line_6 = ""

                waived_late_display = round2(day_exception.get("waive_late_minutes") or 0)
                if raw_late_minutes > 0:
                    if waived_late_display > 0:
                        if effective_late_minutes > 0:
                            line_3 = "Late " + format_minutes_short(effective_late_minutes) + " (Waived " + format_minutes_short(waived_late_display) + ")"
                        else:
                            line_3 = "Late " + format_minutes_short(raw_late_minutes) + " (Waived " + format_minutes_short(waived_late_display) + ")"
                    else:
                        line_3 = "Late " + format_minutes_short(raw_late_minutes)

                waived_early_display = round2(day_exception.get("waive_early_exit_minutes") or 0)
                if raw_early_exit_minutes > 0:
                    if waived_early_display > 0:
                        if effective_early_exit_minutes > 0:
                            line_4 = "Early Exit " + format_minutes_short(effective_early_exit_minutes) + " (Waived " + format_minutes_short(waived_early_display) + ")"
                        else:
                            line_4 = "Early Exit " + format_minutes_short(raw_early_exit_minutes) + " (Waived " + format_minutes_short(waived_early_display) + ")"
                    else:
                        line_4 = "Early Exit " + format_minutes_short(raw_early_exit_minutes)

                if overtime_hours > 0:
