def norm(v):
    if v is None:
        return None
    v = str(v).strip()
    if (not v) or (v.lower() in ("null", "none", "undefined", "nan")):
        return None
    return v

def norm_key(v, default_value="Unspecified"):
    v = norm(v)
    if v:
        return v
    return default_value

def safe_date(v):
    v = norm(v)
    if not v:
        return None
    try:
        return frappe.utils.getdate(v)
    except Exception:
        return None

def safe_datetime(v):
    v = norm(v)
    if not v:
        return None
    try:
        return frappe.utils.get_datetime(v)
    except Exception:
        return None

def inc(d, key, step):
    d[key] = d.get(key, 0) + step

def avg(nums):
    clean = []
    for x in nums:
        if x is not None:
            clean.append(x)
    if not clean:
        return None
    return round(float(sum(clean)) / float(len(clean)), 2)

def hours_between(dt1, dt2):
    if (not dt1) or (not dt2):
        return None
    try:
        diff = dt2 - dt1
        return round(float(diff.total_seconds()) / 3600.0, 2)
    except Exception:
        return None

def month_key(dt):
    return str(dt.year) + "-" + str(dt.month).zfill(2)

def month_label(dt):
    months_en = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun",
        "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    ]
    return months_en[dt.month - 1] + " " + str(dt.year)

def build_month_range(from_dt, to_dt):
    out = []
    y = from_dt.year
    m = from_dt.month

    while (y < to_dt.year) or (y == to_dt.year and m <= to_dt.month):
        dt = frappe.utils.getdate(str(y) + "-" + str(m).zfill(2) + "-01")
        out.append({
            "key": month_key(dt),
            "label": month_label(dt)
        })
        m = m + 1
        if m > 12:
            m = 1
            y = y + 1

    return out

def date_in_range(dt, from_dt, to_dt):
    if not dt:
        return False
    if from_dt and dt < from_dt:
        return False
    if to_dt and dt > to_dt:
        return False
    return True

def sort_dict_payload(d, label_key, value_key, keep_zero):
    items = []
    for k in d:
        v = d.get(k, 0)
        if (not keep_zero) and (not v):
            continue
        items.append({
            label_key: k,
            value_key: v
        })
    items.sort(key=lambda x: x.get(value_key, 0), reverse=True)
    return items

def top_n_payload(d, n, label_key, value_key):
    items = sort_dict_payload(d, label_key, value_key, False)
    return items[:n]

def normalize_status(v):
    v = norm(v)
    if not v:
        return "Unspecified"

    x = v.lower()

    if x in ("draft",):
        return "Draft"

    if x in (
        "request submitted",
        "submitted",
        "submit",
        "submitted request"
    ):
        return "Request Submitted"

    if x in (
        "under verification",
        "verification",
        "under review",
        "in verification"
    ):
        return "Under Verification"

    if x in ("approved", "approve"):
        return "Approved"

    if x in ("rejected", "reject"):
        return "Rejected"

    return v

def normalize_language(v):
    v = norm(v)
    if not v:
        return "Unspecified"

    x = v.lower()

    arabic_vals = ["arabic", "ar", "ara", "عربي", "العربية", "عربى", "عربية"]
    english_vals = ["english", "en", "eng", "انجليزي", "انجليزية", "الانجليزية", "الإنجليزية"]
    french_vals = ["french", "fr", "fra", "فرنسي", "فرنسية", "الفرنسية"]

    if x in arabic_vals:
        return "Arabic"
    if x in english_vals:
        return "English"
    if x in french_vals:
        return "French"

    return v

def normalize_hq(v):
    v = norm(v)
    if not v:
