def get_existing_fields(doctype_name):
    meta = frappe.get_meta(doctype_name)
    out = {
        "name": True,
        "creation": True,
        "modified": True
    }

    for df in meta.fields:
        fn = df.fieldname
        if fn:
            out[fn] = True

    return out

def get_first_existing_field(existing_fields, candidates):
    for f in candidates:
        if existing_fields.get(f):
            return f
    return None

def get_value(row, fieldname):
