def parse_status_history(status_history_text):
    out = []

    txt = norm(status_history_text)
    if not txt:
        return out

    entries = txt.split(",")

    for entry in entries:
        e = norm(entry)
        if not e:
            continue

        parts = e.split("/")

        clean_parts = []
        for p in parts:
            clean_parts.append((p or "").strip())

        if len(clean_parts) < 4:
            continue

        old_status = normalize_status(clean_parts[0])
        new_status = normalize_status(clean_parts[1])
        changed_at = safe_datetime(clean_parts[2])

        user_email = None
        if len(clean_parts) >= 4:
            user_email = "/".join(clean_parts[3:]).strip()

        user_email = norm_key(user_email)

        out.append({
            "old_status": old_status,
            "new_status": new_status,
            "changed_at": changed_at,
            "changed_at_str": str(changed_at) if changed_at else None,
            "user_email": user_email
        })

    out.sort(
        key=lambda x: x.get("changed_at") if x.get("changed_at") else frappe.utils.get_datetime("1900-01-01 00:00:00")
    )
    return out

def extract_status_metrics(status_history_text):
    events = parse_status_history(status_history_text)

    first_submitted_at = None
    first_submitted_by = None

    first_verification_at = None
    first_verification_by = None

    first_decision_at = None
    first_decision_by = None
    first_decision_status = None

    last_status = None
    last_action_at = None
    last_action_by = None

    for ev in events:
        new_status = ev.get("new_status")
        changed_at = ev.get("changed_at")
        user_email = ev.get("user_email")

        if new_status == "Request Submitted" and first_submitted_at is None:
            first_submitted_at = changed_at
            first_submitted_by = user_email

        if new_status == "Under Verification" and first_verification_at is None:
            first_verification_at = changed_at
            first_verification_by = user_email

        if new_status in ("Approved", "Rejected") and first_decision_at is None:
            first_decision_at = changed_at
            first_decision_by = user_email
            first_decision_status = new_status

        last_status = new_status
        last_action_at = changed_at
        last_action_by = user_email

    submitted_to_verification_hours = hours_between(first_submitted_at, first_verification_at)
    verification_to_decision_hours = hours_between(first_verification_at, first_decision_at)
    submitted_to_decision_hours = hours_between(first_submitted_at, first_decision_at)

    current_status = last_status
    is_decided = first_decision_status in ("Approved", "Rejected")

    return {
        "events": events,
        "first_submitted_at": first_submitted_at,
        "first_submitted_by": first_submitted_by,
        "first_verification_at": first_verification_at,
        "first_verification_by": first_verification_by,
        "first_decision_at": first_decision_at,
        "first_decision_by": first_decision_by,
        "first_decision_status": first_decision_status,
        "submitted_to_verification_hours": submitted_to_verification_hours,
        "verification_to_decision_hours": verification_to_decision_hours,
        "submitted_to_decision_hours": submitted_to_decision_hours,
        "current_status": current_status,
        "last_action_at": last_action_at,
        "last_action_by": last_action_by,
        "is_decided": is_decided
    }

