def combine_date_and_time(dt_str, time_value):
    if not time_value:
        return None

    date_obj = frappe.utils.getdate(dt_str)

    time_txt = str(time_value or "")
    if " " in time_txt:
        time_txt = time_txt.split(" ")[-1]

