            shift_start_dt_for_checkin = shift_range_for_checkin[0]
            shift_end_dt_for_checkin = shift_range_for_checkin[1]

        rows_for_day = raw_checkin_day_map.get(key) or []

        grouped_by_time = {}
        for row in rows_for_day:
