            if row_time_key not in grouped_by_time:
                grouped_by_time[row_time_key] = []
            grouped_by_time[row_time_key].append(row)

        checkin_day_map[key] = {
            "first_in": None,
            "last_out": None,
            "last_out_custom_over_night": 0.0
        }

        for row_time_key in grouped_by_time:
            same_time_rows = grouped_by_time.get(row_time_key) or []

            has_in = False
            has_out = False
            selected_row = same_time_rows[0] if same_time_rows else None

            if not selected_row:
                continue

            for same_row in same_time_rows:
                log_type_value = str(same_row.log_type or "").strip().upper()

                if log_type_value == "IN":
                    has_in = True

                elif log_type_value == "OUT":
                    has_out = True
                    selected_row = same_row

            final_log_type = str(selected_row.log_type or "").strip().upper()

            # If the same timestamp exists as IN and OUT, keep only one.
            # If it is closer to shift end, treat it as OUT.
            # If it is closer to shift start, treat it as IN.
            if has_in and has_out and shift_start_dt_for_checkin and shift_end_dt_for_checkin:
                selected_time = frappe.utils.get_datetime(selected_row.time)

                minutes_from_start = abs(
