                )

                minutes_from_end = abs(
                    (selected_time - shift_end_dt_for_checkin).total_seconds() / 60.0
                )

                if minutes_from_end < minutes_from_start:
                    final_log_type = "OUT"
                else:
                    final_log_type = "IN"

            row_time = selected_row.time
            item = checkin_day_map[key]

            if final_log_type == "IN":
                if (not item["first_in"]) or row_time < item["first_in"]:
                    item["first_in"] = row_time

