        shift_name = get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift)

        if shift_name and shift_name in shift_map:
            holiday_list_name = shift_map[shift_name].holiday_list
            if holiday_list_name:
                holiday_row = holiday_map.get(str(holiday_list_name) + "||" + str(dt))
                if holiday_row:
                    weekday = frappe.utils.getdate(dt).weekday()

                    if weekday in [4, 5]:
                        return {
                            "is_holiday": 1,
                            "status": "WEEKEND",
                            "label": "Weekend"
                        }

                    return {
                        "is_holiday": 1,
                        "status": "HOLIDAY",
                        "label": holiday_row.get("description") or "Holiday"
                    }

        weekday = frappe.utils.getdate(dt).weekday()
        if weekday in [4, 5]:
            return {
                "is_holiday": 1,
                "status": "WEEKEND",
                "label": "Weekend"
            }

        return {
            "is_holiday": 0,
            "status": "",
            "label": ""
        }

    def is_holiday(emp, dt):
        return get_day_off_info(emp, dt).get("is_holiday", 0)

    def get_expected_hours(emp, dt):
        if is_holiday(emp, dt):
