    def get_leave_day_hours(leave_row, emp, dt):
        leave_from = frappe.utils.getdate(leave_row.from_date)
        leave_to = frappe.utils.getdate(leave_row.to_date)
        target_date = frappe.utils.getdate(dt)

        if target_date < leave_from or target_date > leave_to:
            return {
                "hours": 0.0,
                "leave_type": leave_row.leave_type or "",
                "label": "",
                "is_hourly": 0,
                "start_dt": None,
                "end_dt": None
            }

        expected_day_hours = get_expected_hours(emp, dt)

        if leave_row.half_day:
            hrs = round2(leave_row.custom_hours or 0)
            if hrs <= 0 and expected_day_hours > 0:
                hrs = round2(expected_day_hours / 2.0)

            start_dt = None
            end_dt = None
            if leave_row.custom_leave_start_time and hrs > 0:
                start_dt = combine_date_and_time(dt, leave_row.custom_leave_start_time)
                end_dt = add_hours_to_datetime(start_dt, hrs)

            label = (leave_row.leave_type or "Leave") + " (" + str(hrs) + "h)"
            if start_dt and end_dt:
                label = (leave_row.leave_type or "Leave") + " " + format_hours_short(hrs) + " " + format_hhmm(start_dt) + " -> " + format_hhmm(end_dt)

            return {
                "hours": hrs,
                "leave_type": leave_row.leave_type or "",
                "label": label,
                "is_hourly": 1,
                "start_dt": start_dt,
                "end_dt": end_dt
            }

        return {
            "hours": round2(expected_day_hours),
            "leave_type": leave_row.leave_type or "",
            "label": (leave_row.leave_type or "Leave") + " (" + str(round2(expected_day_hours)) + "h)",
            "is_hourly": 0,
            "start_dt": None,
            "end_dt": None
        }

    leave_day_map = {}

    for leave_row in leave_rows:
        leave_from = frappe.utils.getdate(leave_row.from_date)
        leave_to = frappe.utils.getdate(leave_row.to_date)

        current_dt = leave_from
        while current_dt <= leave_to:
            if current_dt < from_date_obj or current_dt > to_date_obj:
                current_dt = frappe.utils.add_days(current_dt, 1)
                continue

            dt_str = str(current_dt)
            info = get_leave_day_hours(leave_row, leave_row.employee, dt_str)
            hrs = round2(info.get("hours") or 0)

            if hrs > 0:
                key = str(leave_row.employee) + "||" + dt_str

                if key not in leave_day_map:
                    leave_day_map[key] = {
                        "hours": 0.0,
                        "items": []
                    }

                leave_day_item = leave_day_map[key]
                leave_day_item["hours"] = leave_day_item["hours"] + hrs

                leave_items = leave_day_item.get("items") or []
                leave_items.append({
                    "leave_type": info.get("leave_type") or "",
                    "hours": hrs,
                    "label": info.get("label") or "",
                    "is_hourly": info.get("is_hourly") or 0,
                    "start_dt": info.get("start_dt"),
                    "end_dt": info.get("end_dt")
                })
                leave_day_item["items"] = leave_items

            current_dt = frappe.utils.add_days(current_dt, 1)

    for key in leave_day_map:
