    # -------------------------------------------------------------------------
    # Build employee/day matrix
    # -------------------------------------------------------------------------
    employees_map = {}

    for emp in employee_list:
        emp_details = employee_details_map.get(emp, {})

        base_row = {
            "employee": emp or "",
