            manual_out_dt = combine_date_and_time(dt, day_exception.get("manual_check_out"))

            used_manual_in = False
            used_manual_out = False

            if (not first_in_dt) and manual_in_dt:
                first_in_dt = manual_in_dt
                used_manual_in = True

            if (not last_out_dt) and manual_out_dt:
                last_out_dt = manual_out_dt
