            leave_hours = round2(day_leave.get("hours") or 0)

            if day_off_info.get("is_holiday") and (not first_in_dt) and (not last_out_dt) and (not day_non_onsite) and leave_hours <= 0:
                if day_off_info.get("status") == "WEEKEND":
