                base_row[safe_dt + "_overtime_hours"] = 0.0
                base_row[safe_dt + "_early_exit_minutes"] = 0.0
                continue

            # -----------------------------------------------------------------
            # Build work intervals: Checkin + hourly WFH/DUTY
            # -----------------------------------------------------------------
            work_intervals = []
            activity_lines = []
            fallback_non_onsite_hours = 0.0
