                        covered_early_minutes = intervals_overlap_minutes(work_intervals, last_out_dt, early_cutoff_dt)
                        raw_early_exit_minutes = raw_early_exit_minutes - covered_early_minutes
                        if raw_early_exit_minutes < 0:
