                        debug_parts.append("Waive Late " + str(debug_exception.get("waive_late_minutes") or 0))
                    else:
                        debug_parts.append("Exception NOT Found")

                    debug_parts.append("Raw Early " + format_minutes_short(raw_early_exit_minutes))
                    debug_parts.append("Effective Early " + format_minutes_short(effective_early_exit_minutes))
                    debug_parts.append("Raw Late " + format_minutes_short(raw_late_minutes))
                    debug_parts.append("Effective Late " + format_minutes_short(effective_late_minutes))

                    extra_lines.append("Debug " + " - ".join(debug_parts))

                if extra_lines:
                    line_6 = " | ".join(extra_lines)

                status_code = "PRESENT"
                if (not first_in_dt) or (not last_out_dt):
                    status_code = "INCOMPLETE"

                base_row[safe_dt] = make_day_cell(
                    status_code,
                    top_value,
                    line_2,
                    line_3,
                    line_4,
                    line_5,
                    line_6,
                    actual_work_hours,
                    effective_late_minutes
                )

                base_row[safe_dt + "_leave_hours"] = round2(leave_hours)
                base_row[safe_dt + "_overtime_hours"] = round2(overtime_hours)
                base_row[safe_dt + "_early_exit_minutes"] = round2(effective_early_exit_minutes)
                continue

            # Non-on-site only: WFH / DUTY without checkin
            if day_non_onsite:
                non_onsite_minutes = interval_minutes_total(work_intervals)
                non_onsite_hours = round2(non_onsite_minutes / 60.0)

                if non_onsite_hours <= 0:
                    non_onsite_hours = round2(day_non_onsite.get("total_hours") or 0)

                shift_name = get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift)
                shift_doc = shift_map.get(shift_name) if shift_name else None

                overtime_hours = 0.0
                if shift_doc:
                    shift_range = get_shift_start_end_datetimes(shift_doc, dt)
                    shift_start_dt = shift_range[0]
                    shift_end_dt = shift_range[1]

                    if shift_start_dt and shift_end_dt:
                        overtime_minutes = intervals_outside_shift_minutes(work_intervals, shift_start_dt, shift_end_dt)
                        overtime_hours = round2(overtime_minutes / 60.0)

                status_code = main_non_onsite_status or "WFH"
                line_2 = main_non_onsite_label or "Work From Home"

                line_3 = ""
                line_4 = ""
                line_5 = ""
                line_6 = ""

                if overtime_hours > 0:
                    line_5 = "Overtime " + format_hours_short(overtime_hours)

                extra_lines = []
                for al in activity_lines:
                    if al:
                        extra_lines.append(al)

                if leave_hours > 0 and day_leave.get("items"):
                    leave_txt_parts = []
                    for li in day_leave.get("items"):
                        if li.get("is_hourly") and li.get("start_dt") and li.get("end_dt"):
                            leave_txt_parts.append(
                                format_hours_short(li.get("hours") or 0) + " " + format_hhmm(li.get("start_dt")) + " -> " + format_hhmm(li.get("end_dt")) + " (" + (li.get("leave_type") or "Leave") + ")"
                            )
                        else:
                            leave_txt_parts.append(
                                format_hours_short(li.get("hours") or 0) + " (" + (li.get("leave_type") or "Leave") + ")"
                            )
                    extra_lines.append("Leave " + ", ".join(leave_txt_parts))

                if extra_lines:
                    line_6 = " | ".join(extra_lines)

                base_row[safe_dt] = make_day_cell(
                    status_code,
                    format_hours_short(non_onsite_hours),
                    line_2,
                    line_3,
                    line_4,
                    line_5,
                    line_6,
                    non_onsite_hours,
                    0
                )

                base_row[safe_dt + "_leave_hours"] = round2(leave_hours)
                base_row[safe_dt + "_overtime_hours"] = round2(overtime_hours)
                base_row[safe_dt + "_early_exit_minutes"] = 0.0
                continue

            # Leave only
            if leave_hours > 0:
                line_6 = ""
                if day_leave.get("items"):
                    leave_txt_parts = []
                    for li in day_leave.get("items"):
                        if li.get("is_hourly") and li.get("start_dt") and li.get("end_dt"):
                            leave_txt_parts.append(
                                format_hours_short(li.get("hours") or 0) + " " + format_hhmm(li.get("start_dt")) + " -> " + format_hhmm(li.get("end_dt")) + " (" + (li.get("leave_type") or "Leave") + ")"
                            )
