            # Unjustified hours are calculated per day, then accumulated.
            # This prevents overtime or extra work on another day from covering an unexcused absence day.
            day_work_with_leave = cell_hours + day_leave_hours
            day_unjustified_hours = day_expected_hours - day_work_with_leave

            if day_unjustified_hours < 0:
