        row["overtime_hours"] = overtime_hours
        row["overtime_hours_display"] = format_hours_day_short(overtime_hours, employee_display_day_hours)

        row["expected_hours"] = expected_hours
        row["expected_hours_display"] = format_hours_day_short(expected_hours, employee_display_day_hours)

        row["unjustified_hours"] = unjustified_hours
        row["unjustified_hours_display"] = format_hours_day_short(unjustified_hours, employee_display_day_hours)

        row["late_entry_hours"] = late_entry_hours
        row["late_entry_hours_display"] = format_hours_day_short(late_entry_hours, employee_display_day_hours)

