# Server Script
# Reference DocType: Attendance Request
# Event: After Submit

ACTIVITY_DOCTYPE = "Attendance Activity"

REQUEST_TYPE_FIELD = "reason"
FROM_TIME_FIELD = "start_time"
HOURS_FIELD = "work_hours"
IS_HOURLY_FIELD = "hourly_request"
INCLUDE_HOLIDAYS_FIELD = "include_holidays"


def round2(v):
    return round(float(v or 0), 2)


def normalize_activity_type(value):
    value = str(value or "").strip()

    mapping = {
        "On Duty": "On Duty",
        "Work From Home": "Work From Home",
        "WFH": "Work From Home",
        "Training": "Training",
        "Manual Work": "Manual Work",
    }

    return mapping.get(value, value)


def add_hours_to_time(base_date, start_time, hours):
    start_dt = frappe.utils.get_datetime(
        str(base_date) + " " + str(start_time)
    )

    end_dt = frappe.utils.add_to_date(
        start_dt,
        hours=float(hours or 0),
        as_datetime=True
    )

    return end_dt.time()


activity_type = normalize_activity_type(doc.get(REQUEST_TYPE_FIELD))

allowed_activity_types = [
    "On Duty",
    "Work From Home",
    "Training",
    "Manual Work"
]

if activity_type in allowed_activity_types:

    from_time = doc.get(FROM_TIME_FIELD)
    hours = round2(doc.get(HOURS_FIELD))
    is_hourly = 1 if doc.get(IS_HOURLY_FIELD) else 0
    include_holidays = 1 if doc.get(INCLUDE_HOLIDAYS_FIELD) else 0

    if hours <= 0:
        frappe.throw("Work Hours is required")

    if is_hourly and not from_time:
        frappe.throw("Start Time is required for hourly request")

    if is_hourly and str(doc.from_date) != str(doc.to_date):
        frappe.throw("Hourly request must be for one day only")

    old_rows = frappe.get_all(
        ACTIVITY_DOCTYPE,
        filters={
            "source_doctype": doc.doctype,
            "source_name": doc.name
        },
        fields=["name"]
    )

    for row in old_rows:
        frappe.db.set_value(
            ACTIVITY_DOCTYPE,
            row.name,
            {
                "status": "Cancelled",
                "notes": "Auto-cancelled before rebuild"
            }
        )

    emp = frappe.get_doc("Employee", doc.employee)

    from_date_obj = frappe.utils.getdate(doc.from_date)
    to_date_obj = frappe.utils.getdate(doc.to_date)

    # ---------------------------------------------------------
    # Build Shift Map مثل كود الـ API
    # ---------------------------------------------------------
    employee_date_shift_map = {}
    shift_names = []
    shift_seen = {}

    if emp.default_shift:
        shift_names.append(emp.default_shift)
        shift_seen[emp.default_shift] = 1

    shift_assignments = frappe.get_all(
        "Shift Assignment",
        filters={
            "employee": doc.employee,
            "start_date": ["<=", to_date_obj]
        },
        fields=[
            "employee",
            "shift_type",
            "start_date",
            "end_date"
        ],
        order_by="employee asc, start_date asc"
    )

    for sa in shift_assignments:

        if not sa.employee or not sa.shift_type or not sa.start_date:
            continue

        assignment_start = frappe.utils.getdate(sa.start_date)

        if sa.end_date:
            assignment_end = frappe.utils.getdate(sa.end_date)
        else:
            assignment_end = to_date_obj

        if assignment_start < from_date_obj:
            assignment_start = from_date_obj

        if assignment_end > to_date_obj:
            assignment_end = to_date_obj

        if assignment_start > assignment_end:
            continue

        if sa.shift_type not in shift_seen:
            shift_names.append(sa.shift_type)
            shift_seen[sa.shift_type] = 1

        d = assignment_start

        while d <= assignment_end:
            employee_date_shift_map[
                str(sa.employee) + "||" + str(d)
            ] = sa.shift_type

            d = frappe.utils.add_days(d, 1)

    # ---------------------------------------------------------
    # Get Shift Type + Holiday List
    # ---------------------------------------------------------
    shift_map = {}
    holiday_list_names = []
    holiday_list_seen = {}

    if shift_names:
        shift_rows = frappe.get_all(
            "Shift Type",
            filters={
                "name": ["in", shift_names]
            },
            fields=[
                "name",
                "holiday_list"
            ]
        )

        for shift_row in shift_rows:
            shift_map[shift_row.name] = shift_row

            if shift_row.holiday_list:
                if shift_row.holiday_list not in holiday_list_seen:
                    holiday_list_names.append(shift_row.holiday_list)
                    holiday_list_seen[shift_row.holiday_list] = 1

    # ---------------------------------------------------------
    # Get Holidays
    # ---------------------------------------------------------
    holiday_map = {}

    if holiday_list_names:
        holiday_rows = frappe.get_all(
            "Holiday",
            filters={
                "parent": ["in", holiday_list_names],
                "holiday_date": [
                    "between",
                    [
                        str(from_date_obj),
                        str(to_date_obj)
                    ]
                ]
            },
            fields=[
                "parent",
                "holiday_date",
                "description"
            ]
        )

        for hr in holiday_rows:
            holiday_map[
                str(hr.parent) + "||" + str(hr.holiday_date)
            ] = 1

    # ---------------------------------------------------------
    # Create Attendance Activity
    # ---------------------------------------------------------
    current_date = from_date_obj
    end_date = to_date_obj

    while current_date <= end_date:

        date_key = str(doc.employee) + "||" + str(current_date)

        shift_name = employee_date_shift_map.get(date_key)

        if not shift_name:
            shift_name = emp.default_shift

        holiday_list_name = None

        if shift_name and shift_name in shift_map:
            holiday_list_name = shift_map[shift_name].holiday_list

        is_holiday = 0

        if holiday_list_name:
            holiday_key = str(holiday_list_name) + "||" + str(current_date)

            if holiday_map.get(holiday_key):
                is_holiday = 1

        # نفس منطق كود الـ API عندك: الجمعة والسبت عطلة
        weekday = frappe.utils.getdate(current_date).weekday()

        if weekday in [4, 5]:
            is_holiday = 1

        # إذا Include Holidays غير مفعّل، نتخطى العطل
        if not include_holidays and is_holiday:
            current_date = frappe.utils.add_days(current_date, 1)
            continue

        to_time = None

        if is_hourly:
            to_time = add_hours_to_time(
                current_date,
                from_time,
                hours
            )

        activity = frappe.new_doc(ACTIVITY_DOCTYPE)

        activity.employee = doc.employee
        activity.employee_name = emp.employee_name
        activity.attendance_date = current_date

        activity.company = emp.company
        activity.department = emp.department

        activity.activity_type = activity_type

        activity.from_time = from_time if is_hourly else None
        activity.to_time = to_time if is_hourly else None

        activity.hours = hours
        activity.is_hourly = is_hourly

        activity.source_doctype = doc.doctype
        activity.source_name = doc.name

        activity.status = "Approved"
        activity.notes = "Created automatically from " + doc.name

        activity.insert(ignore_permissions=True)

        current_date = frappe.utils.add_days(current_date, 1)

